-- plant_species 초기 데이터 (generate_plant_species_sql.py 로 생성, 직접 수정하지 말 것)
-- 앱을 한 번 띄워 테이블이 만들어진 뒤 실행한다. 여러 번 실행해도 중복되지 않는다.
BEGIN;
INSERT INTO plant_species (species_id, scientific_name, korean_name, watering_cycle_code,
    sunlight_level_code, difficulty_level, is_pet_friendly, optimal_temp_celsius,
    management_tip_detail, toxicity_info, official_image_url, is_verified_by_admin,
    created_at, updated_at)
VALUES
(1, 'Begonia spp.', '베고니아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '베고니아는 열대 및 아열대 지역이 원산지인 식물로, 잎이 비대칭인 것이 특징이에요. 다양한 종류가 있으며, 관엽 베고니아와 꽃 베고니아로 나뉘어 실내에서 많이 기릅니다. 베고니아는 증산작용이 활발하여 실내 습도를 높이는 데 도움이 돼요.', '베고니아는 일반적으로 독성이 없지만, 일부 종은 민감한 사람에게 알레르기 반응을 일으킬 수 있어요.', '/files/nongsaro_img/7478360e-f034-4551-a408-b6dad474b5cf.jpg', true, now(), now()),
(2, 'Rhapis excelsa', '관음죽', 'NORMAL', 'LOW', 'NORMAL', false, '16~20℃', '관음죽은 야자과에 속하는 식물로, 한국, 일본, 중국 남부가 원산지예요. 이 식물은 그늘과 추위에 잘 견디며, 병해충에도 강해 실내에서 기르기 쉬운 식물로 알려져 있어요. 특히 암모니아 가스를 효과적으로 제거하여 화장실에 두기 적합해요.', '관음죽의 수액은 피부나 점막을 자극할 수 있어요. 따라서 피부에 닿지 않도록 주의해야 해요.', '/files/nongsaro_img/cd734a05-056f-4227-8e56-93be7f2cbdc6.jpg', true, now(), now()),
(3, 'Aerides japonica', '나도풍란', 'INFREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '나도풍란은 난초과에 속하는 식물로, 한국과 일본 등 아시아 지역에 자생합니다. 이 식물은 주로 바위나 나무에 붙어 자라며, 흰색의 향기로운 꽃을 피웁니다. 공기 중 유해물질인 포름알데히드를 효과적으로 제거하여 실내 공기 정화에 도움을 줍니다.', '나도풍란은 독성이 없으므로 안전하게 키울 수 있어요.', '/files/nongsaro_img/cd78e323-382f-4f79-bdfa-f1fc265dcd0f.jpg', true, now(), now()),
(4, 'Pittosporum tobira', '돈나무', 'NORMAL', 'MEDIUM', 'EASY', false, '16~20℃', '돈나무는 제주도에서 ''똥낭''으로 불리며, 열매에서 나오는 점액질 때문에 곤충이 모여들어 붙여진 이름이에요. 주로 남부 해안가에서 자라는 상록 관목으로, 최대 2~3m까지 자라며 잎은 광택이 있고 둥근형이에요. 꽃은 노랑색 또는 흰색으로 작고, 열매는 둥글며 붉은 씨가 드러나요.', '돈나무는 애완동물에게 해로울 수 있어요. 섭취 시 구토나 설사를 유발할 수 있으니 주의해야 해요.', '/files/nongsaro_img/f27919fe-b24f-4990-9126-82aa6743becd.jpg', true, now(), now()),
(5, 'Dracaena deremensis ''Warneckii''', '드라세나 와네키', 'NORMAL', 'MEDIUM', 'EASY', false, '16~20℃', '드라세나 와네키는 아프리카가 원산지인 공기정화 식물로, 실내에서 키우기 쉬운 식물이에요. 이 식물은 포름알데히드, 벤젠, 톨루엔 등의 오염 물질을 제거하는 데 효과적이에요. 잎은 길고 줄무늬가 있으며, 환경에 따라 최대 3m까지 자랄 수 있어요.', '드라세나 와네키는 애완동물에게 해로울 수 있어요. 섭취 시 구토나 설사를 유발할 수 있으니 주의하세요.', '/files/nongsaro_img/118dfd96-2f87-48ee-9980-12142bfa828d.jpg', true, now(), now()),
(6, 'Dracaena marginata', '드라세나 마지나타', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '드라세나 마지나타는 1960년대부터 실내식물로 많이 알려졌어요. 이 식물은 잎이 창처럼 가늘고 길며, 실내 공기 정화에 탁월한 능력을 가지고 있어요. 특히 자일렌과 트리클로로에틸렌 같은 독성 물질을 제거하는 데 효과적이에요.', '드라세나 마지나타는 독성이 없어요.', '/files/nongsaro_img/28809f5c-7105-4914-8378-bcabca3dcb40.jpg', true, now(), now()),
(7, 'Dracaena fragrans var. massangeana', '맛상게아나 드라세나', 'NORMAL', 'LOW', 'EASY', false, '16~20℃', '맛상게아나 드라세나는 열대 원산종의 원예 변종으로 대형종이에요. 실내에서는 3m까지 자랄 수 있으며, 줄기 윗부분을 잘라주면 새로운 싹이 나와 원기 회복에 도움이 돼요. 사무실이나 거실에 두면 공간을 시원하게 연출할 수 있어요.', '애완동물에게 해로울 수 있어요. 섭취 시 구토나 설사를 유발할 수 있어요.', '/files/nongsaro_img/82b00586-9ad3-4eca-a395-2ac4e62520d0.jpg', true, now(), now()),
(8, 'Dizygotheca elegantissima', '디지고데카', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '디지고데카는 두릅나무과에 속하는 상록 목본성 관엽식물로, 태평양의 여러 섬들이 원산지예요. 이 식물은 손가락을 펼친 듯한 섬세한 잎이 특징이며, 실내에서 관상용으로 많이 사용돼요. 직사광선을 피하고 반그늘에서 잘 자라며, 포름알데히드 제거 능력이 뛰어나 공기정화 식물로도 인기가 많아요.', '디지고데카는 독성이 없어서 안전하게 키울 수 있어요.', '/files/nongsaro_img/a428c413-590c-4c44-853a-fd72a54d7a93.jpg', true, now(), now()),
(9, 'Trachelospermum asiaticum', '마삭줄', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '마삭줄은 상록의 덩굴성 목본으로, 흑갈색 줄기를 가지고 있으며 약 5m까지 자랍니다. 5~6월에 흰색에서 노란색으로 변하는 꽃을 피우며, 잎과 줄기는 약용으로 사용됩니다. 이 식물은 내건성, 내한성, 내공해성이 강하며, 이식이 어려운 특징을 가지고 있습니다.', '마삭줄은 독성이 없어 안전하게 키울 수 있습니다.', '/files/nongsaro_img/c9c45dbd-89a5-427b-80c8-89a57bd0fd09.jpg', true, now(), now()),
(10, 'Sansevieria trifasciata', '산세베리아', 'NORMAL', 'LOW', 'EASY', false, '21~25℃', '산세베리아는 이탈리아 산 세베로의 왕자 라이문도 디 산그로를 기리기 위해 이름이 붙여졌어요. 공기정화식물로 유명하며, CAM식물로서 밤에도 이산화탄소를 흡수해요. 애완동물이 섭취하면 구토나 설사를 일으킬 수 있어 주의가 필요해요.', '산세베리아는 섭취 시 구토와 설사를 유발할 수 있는 독성을 가지고 있어요. 특히 애완동물에게 위험할 수 있어 주의가 필요해요.', '/files/nongsaro_img/6a7bb281-1b50-4c47-a644-b217899451d7.jpg', true, now(), now()),
(11, 'Cyclamen persicum', '시클라멘', 'NORMAL', 'MEDIUM', 'HARD', false, '16~20℃', '시클라멘은 앵초과에 속하는 덩이줄기 구근식물로, 주로 겨울철에 꽃을 피우며 실내에서 재배하기 적합해요. 꽃은 보라색, 분홍색, 빨강색, 흰색 등 다양한 색상을 가지며, 하트모양의 잎과 함께 아름다움을 더해요. 통풍이 잘 되는 서늘한 환경을 선호하며, 여름철에는 차광을 통해 온도를 조절해주는 것이 중요해요.', '시클라멘은 구근에 독성이 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/424b39a8-407b-4983-a274-00500998705d.jpg', true, now(), now()),
(12, 'Cymbidium spp.', '심비디움', 'INFREQUENT', 'MEDIUM', 'HARD', true, '21~25℃', '심비디움은 열대 및 아열대 아시아와 호주가 원산지인 난초과 식물이에요. 다양한 꽃 색을 가지며, 겨울철에 꽃이 피고 화분용이나 절화로 많이 사용돼요. 뿌리가 꽉 차기 전, 3~4월에 분갈이를 하는 것이 좋으며, 과습에 주의해야 해요.', '독성 정보는 없지만, 어린이와 반려동물이 접근하지 않도록 주의해 주세요.', '/files/nongsaro_img/91033949-6da3-420c-9f4e-a5d67954c2f9.JPG', true, now(), now()),
(13, 'Syngonium podophyllum', '싱고니움', 'FREQUENT', 'MEDIUM', 'NORMAL', false, '21~25℃', '싱고니움은 천남성과에 속하는 덩굴성 식물로, 주로 실내에서 관엽식물로 기릅니다. 다양한 잎 색상과 무늬를 가지며, 공기 중의 암모니아와 포름알데히드를 효과적으로 제거하는 능력을 지녔어요. 고온다습한 환경에서 잘 자라며, 줄기를 자르면 나오는 즙액은 식용 시 위험할 수 있어 주의가 필요해요.', '싱고니움의 즙액은 섭취 시 구토나 설사를 유발할 수 있어요. 어린이와 반려동물의 접근을 피하세요.', '/files/nongsaro_img/e24773e4-0e4e-4003-85e5-f57d51f2b71d.jpg', true, now(), now()),
(14, 'Epipremnum aureum', '스킨답서스', 'NORMAL', 'LOW', 'NORMAL', false, '21~25℃', '스킨답서스는 천남성과에 속하는 덩굴성 식물로, 주로 실내에서 기르기 쉽고 관리가 용이해요. 이 식물은 일산화탄소 제거 능력이 뛰어나 주방에서 많이 사용되며, 어두운 곳에서도 잘 자라요. 칼슘옥살레이트 성분을 포함하고 있어 애완동물에게는 독성이 있을 수 있어요.', '칼슘옥살레이트 성분이 있어 섭취 시 구토나 설사를 유발할 수 있어요. 피부에 닿으면 자극을 줄 수 있으니 주의하세요.', '/files/nongsaro_img/f3cab31e-d9b8-4fc1-b78b-d07481ef9e7e.gif', true, now(), now()),
(15, 'Spathiphyllum wallisii', '스파티필름', 'NORMAL', 'LOW', 'NORMAL', false, '21~25℃', '스파티필름은 천남성과에 속하는 상록 다년초로, 콜롬비아와 베네수엘라가 원산지예요. 이 식물은 흰색의 불염포와 광택 있는 녹색 잎을 가지고 있어 실내에서 관상용으로 인기가 많아요. 또한, 공기 중의 다양한 오염물질을 제거하는 능력이 뛰어나 공기정화식물로도 널리 알려져 있어요.', '스파티필름은 칼슘 옥살레이트를 함유하고 있어 섭취 시 구토, 설사 등의 증상을 유발할 수 있어요.', '/files/nongsaro_img/022bc6d5-979d-41c3-9a4d-f97bcf4a1f69.gif', true, now(), now()),
(16, 'Hedera helix', '아이비', 'NORMAL', 'MEDIUM', 'EASY', false, '16~20℃', '아이비는 두릅나무과에 속하는 덩굴성 식물로, 유럽과 서아시아, 북아프리카가 원산지예요. 주로 실내에서 기르기 쉬운 식물로, 다양한 잎 모양과 색깔을 가지고 있어 장식용으로 인기가 많아요. 아이비는 공기정화 능력이 뛰어나며, 음이온 발생량이 많아 실내 환경 개선에 도움을 줘요.', '아이비의 잎과 줄기에서 나오는 진액은 피부에 자극을 줄 수 있어요. 섭취 시 구토나 설사를 유발할 수 있으니 주의해야 해요.', '/files/nongsaro_img/765b1d13-c109-403d-b6d3-c44a1fdcece7.jpg', true, now(), now()),
(17, 'Peperomia caperata', '페페로미아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '페페로미아는 후추과에 속하는 다육질의 잎을 가진 식물로, 중앙 아메리카가 원산지예요. 다양한 크기와 모양으로 실내 관엽식물로 인기가 많으며, 자일렌과 포름알데히드를 제거하는 공기정화 능력이 우수해요. 생장이 느린 편이라 아담한 크기의 화분에서 기르기 적합하며, 테라리움이나 접시정원에서도 많이 이용돼요.', '독성이 없어 안전하게 기를 수 있어요.', '/files/nongsaro_img/ae5f1cd3-817f-4288-b78c-d675f5137ec3.jpg', true, now(), now()),
(18, 'Begonia X hiemalis', '베고니아', 'NORMAL', 'HIGH', 'NORMAL', true, '21~25℃', '베고니아는 남아메리카가 원산지인 베고니아과의 식물로, 주로 화단이나 실내에서 관상용으로 많이 기릅니다. 이 식물은 높은 광도를 필요로 하지만 직사광선에 노출되면 잎이 탈 수 있어 주의가 필요해요. 베고니아는 다양한 색상의 꽃을 피우며, 잎을 통한 증산작용으로 실내 습도를 높이는 데 도움을 줍니다.', '베고니아는 일반적으로 독성이 없지만, 일부 품종은 민감한 사람에게 피부 자극을 유발할 수 있습니다.', '/files/nongsaro_img/e7f52f66-a627-483c-93f9-6faf049f9521.jpg', true, now(), now()),
(19, 'Oncidium spp.', '온시디움', 'INFREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '온시디움은 중남미와 열대아시아가 원산지인 난초과 식물로, 주로 노란색 꽃을 피우며 춤추는 나비를 연상케 합니다. 착생란으로 다른 식물의 표면이나 바위에 붙어 자라며, 실내에서 기르기 적합합니다. 공기정화 능력은 낮지만, 화려한 꽃으로 실내 장식용으로 인기가 많습니다.', '온시디움은 독성이 없어서 안전하게 키울 수 있어요.', '/files/nongsaro_img/66af8cb7-6450-4e21-b407-a19d1a8e85b7.jpg', true, now(), now()),
(20, 'Ardisia japonica', '자금우', 'NORMAL', 'LOW', 'EASY', false, '16~20℃', '자금우는 한국, 일본, 중국에 자생하는 상록활엽성 관목이에요. 주로 산지의 숲 밑에서 서식하며, 사계절 항상 푸른 잎을 가지고 있어요. 음이온 발생량이 우수하여 실내 공기정화에 도움이 되며, 톨루엔 제거 능력도 뛰어나요.', '자금우의 모든 부분은 섭취 시 독성이 있어 주의해야 해요. 특히 어린아이와 애완동물이 있는 가정에서는 조심해야 해요.', '/files/nongsaro_img/30ca0dd3-b2e4-45a3-812f-a29ad890955f.jpg', true, now(), now()),
(21, 'Aechmea fasciata', '아나나스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '아나나스는 파인애플과에 속하는 식물로, 주로 브라질의 열대 정글에서 자생해요. 이 식물은 색깔이 선명한 포엽이 아름다워 관상용으로 인기가 많아요. 로제트 형태의 잎은 은빛 녹색 줄무늬가 있으며, 가장자리에 가시가 돋아 있어요.', '아나나스는 독성이 없어요.', '/files/nongsaro_img/f34f34e4-4490-4532-9926-40504b74d774.jpg', true, now(), now()),
(22, 'Chlorophytum comosum', '접란', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '접란은 백합과에 속하는 식물로, 아프리카가 원산지예요. 이 식물은 공기 중의 포름알데히드와 일산화탄소를 제거하는 능력이 뛰어나 거실이나 주방에 적합해요. 중앙에 노란색이나 크림색 줄무늬를 가진 초록색 잎이 특징이며, 공중에서 번식하는 새끼식물이 매력적이에요.', '접란은 독성이 없어 반려동물과 함께 키우기 좋아요.', '/files/nongsaro_img/301f2566-3519-4898-bcb7-4fbd7945fd6f.jpg', true, now(), now()),
(23, 'Pelargonium hortorum', '제라니움', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '제라니움은 남아프리카 원산의 원예교배종으로, 세계적으로 널리 이용되는 분화식물이에요. 봄부터 가을까지 화려한 붉은색 꽃을 피우며, 잎과 줄기에서 나는 특유의 향기로 곤충을 쫓는 효과가 있어요. 기르기 쉬워 관상용으로 많이 사용되며, 잎에서 나는 방향유는 포푸리, 차, 향수 등에도 쓰여요.', '제라니움은 일반적으로 독성이 없으나, 민감한 사람에게는 피부 자극을 일으킬 수 있어요.', '/files/nongsaro_img/491de543-13a9-4411-a83d-f85ce2e7beef.jpg', true, now(), now()),
(24, 'Peperomia puteolata', '페페로미아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '페페로미아는 중앙 아메리카가 원산지인 후추과 식물로, 약 500종 이상의 다양한 종류가 있어 실내 관엽식물로 인기가 많아요. 생장이 더디고 아담한 크기로, 접시정원이나 테라리움에서도 많이 이용돼요. 잎은 다육질로 무늬나 반점이 있으며, 번식이 쉬운 편이에요.', '페페로미아는 독성이 거의 없고 안전한 식물이에요.', '/files/nongsaro_img/690c88f8-1d37-401c-a4d6-a81d4edc8522.jpg', true, now(), now()),
(25, 'Gardenia jasminoides', '치자나무', 'INFREQUENT', 'MEDIUM', 'EASY', true, '21~25℃', '치자나무는 꼭두서니과에 속하는 상록 관목으로, 아시아가 원산지예요. 향기로운 흰색 꽃과 노란색 열매를 맺으며, 꽃은 주로 봄과 여름에 피어요. 실내에서도 잘 자라며 공기 정화 능력이 있어 인기가 많아요.', '치자나무는 일반적으로 독성이 없어요.', '/files/nongsaro_img/eb040a86-f785-40c9-aace-d2b9367d8dee.jpg', true, now(), now()),
(26, 'Calathea makoyana', '칼라데아 마코야나', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '칼라데아 마코야나는 마란타과에 속하는 식물로, 중앙 아메리카가 원산지예요. 이 식물은 공작새의 꼬리를 닮은 화려한 잎 무늬로 인해 ''Peacock plant''라는 이름을 가지고 있어요. 실내에서 키우기 적합하지만 관리가 까다로워 경험자에게 추천돼요.', '독성 정보가 없어요.', '/files/nongsaro_img/2f14c622-29c0-4e87-b5b7-00e388f27a04.jpg', true, now(), now()),
(27, 'Kalanchoe blossfeldiana', '칼랑코에', 'NORMAL', 'MEDIUM', 'EASY', false, '16~20℃', '칼랑코에는 마다가스카르가 원산지인 다육식물로, 다양한 색상의 꽃을 피우는 것이 특징이에요. 주로 가을과 겨울에 인기가 많으며, 관리가 쉬워 초보자도 키우기 좋습니다. 실내 오염 물질 제거 능력은 낮지만, 꽃이 피었을 때 실내를 아름답게 꾸며줘요.', '칼랑코에의 모든 부분은 섭취 시 독성이 있어요. 특히 어린이나 애완동물이 먹지 않도록 주의해야 해요.', '/files/nongsaro_img/2df4786a-c613-42bf-b078-f32ce1c734ec.jpg', true, now(), now()),
(28, 'Pachira aquatica', '파키라', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '파키라는 중앙 아메리카가 원산지이며, 물밤나무과에 속하는 관엽식물이에요. 외국에서는 ''Money tree''로 불리며, 잎과 꽃은 식용이 가능하고 열매는 땅콩 맛이 납니다. 실내에서 이국적인 정취를 풍기며 인기 있는 식물이에요.', '파키라는 해독작용이 있어 독성이 없어요.', '/files/nongsaro_img/d190d0f2-e649-4e03-a7ee-984a5f3ce6de.jpg', true, now(), now()),
(29, 'Euphorbia pulcherrima', '포인세티아', 'FREQUENT', 'HIGH', 'NORMAL', false, '21~25℃', '포인세티아는 멕시코가 원산지인 대극과의 식물로, 크리스마스 시즌에 특히 인기가 많아요. 이 식물은 추위에 약하며, 잎에서 나오는 흰색 즙액은 피부나 눈에 염증을 일으킬 수 있어 주의가 필요해요. 포인세티아는 높은 광도와 적절한 온도에서 잘 자라며, 실내에서 관상용으로 많이 기르죠.', '포인세티아의 흰색 즙액은 피부나 눈에 염증을 일으킬 수 있어요. 어린이와 반려동물이 섭취하지 않도록 주의해야 해요.', '/files/nongsaro_img/a003dbf4-c019-48d1-9328-1fb16e8ea4c3.jpg', true, now(), now()),
(30, 'Philodendron selloum', '필로덴드론 셀룸', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '필로덴드론 셀룸은 브라질과 파라과이 원산의 천남성과 식물로, 실내 재배에 적합해요. 이 식물은 큰 물결무늬의 잎을 가지고 있으며, 포름알데히드 제거 능력이 우수해요. 공기가 건조하고 빛이 잘 들지 않는 환경에서도 잘 견디며, 적절한 관리로 오랫동안 기를 수 있어요.', '필로덴드론 셀룸은 칼슘 옥살레이트를 함유하고 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/d512c3b9-13b4-4b0f-b5af-b76b6eb26eae.jpg', true, now(), now()),
(31, 'Hoya carnosa', '호야', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '호야는 박주가리과에 속하는 덩굴성 상록다년초로, 주로 동남아시아와 오스트레일리아에 분포해요. 이 식물은 자일렌 제거에 뛰어난 공기정화 능력을 가지고 있으며, 포름알데히드 제거에도 효과적이에요. 꽃은 연한 분홍색으로 봄과 여름에 피며, 충분한 빛을 받으면 더욱 잘 자라요.', '호야는 독성이 없으므로 안전하게 키울 수 있어요.', '/files/nongsaro_img/0d4ab361-2575-4bca-899a-f4764526fe54.jpg', true, now(), now()),
(32, 'Trachelospermum asiaticum var. intermedium Nakai', '마삭줄', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '마삭줄은 한국에서 자생하는 상록 덩굴성 목본으로, 줄기가 길게 뻗어 바위나 나무를 기어오릅니다. 5~6월에 피는 꽃은 흰색에서 노란색으로 변하며, 취산꽃차례를 이룹니다. 포름알데히드 제거 능력이 우수하여 실내 공기 정화에 도움을 줍니다.', '독성 정보가 없습니다.', '/files/nongsaro_img/49b3eaf3-ddcf-4c2c-ae16-42d9f139e4c4.jpg', true, now(), now()),
(33, 'Gaultheria procumbens', '파스향나무', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '파스향나무는 진달래과의 작은 관목으로 척박한 산성토양에서 잘 자라며 키는 20cm 정도로 포복형이에요. 암석정원에 잘 어울리며, 식용, 지피, 약용, 향기, 관엽, 관화, 관실 등 다양한 용도로 사용돼요. 여름철에는 분홍색과 흰색의 꽃을 피우고, 빨간색의 열매를 맺어요.', '독성 정보는 없어요.', '/files/nongsaro_img/d2dd6293-f634-45e2-98f0-f677be93374e.jpg', true, now(), now()),
(34, 'Dracaena sanderiana', '개운죽', 'FREQUENT', 'LOW', 'EASY', false, '16~20℃', '개운죽은 드라세나속의 관엽식물로, 대나무를 닮은 외형 때문에 이름이 붙여졌어요. 서부 아프리카가 원산지이며, 실내에서 잘 자라는 식물이에요. 관리가 쉬워 초보자도 키우기 적합해요.', '개운죽은 독성이 있어 애완동물이나 어린이가 섭취하지 않도록 주의해야 해요. 섭취 시 구토나 설사를 유발할 수 있어요.', '/files/nongsaro_img/a3cd1a9f-e0d0-4b78-a960-fbb00b88283e.jpg', true, now(), now()),
(35, 'Cupressus macrocarpa ''Wilma''', '율마', 'NORMAL', 'HIGH', 'NORMAL', true, '16~20℃', '율마는 부드러운 연두빛의 침엽수로, 실내에서 허브 향을 느낄 수 있는 식물이에요. 바람에 약하며 줄기 아랫부분의 잎이 떨어질 수 있지만, 토피아리 형식으로 키우면 장식 효과가 뛰어나요. 크리스마스 트리로도 활용할 수 있어요.', '특별한 독성은 없어요.', '/files/nongsaro_img/54858d86-9611-4c63-87ee-87aac8cf707e.jpg', true, now(), now()),
(36, 'Caryota mitis', '공작야자', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '공작야자는 동남아시아와 인도네시아가 원산지인 식물로, 주로 실내에서 관상용으로 키워요. 잎은 광택이 있으며 굵고 선명한 질감을 가지고 있어요. 포름알데히드, 벤젠, 톨루엔 등의 공기 오염 물질을 제거하는 능력이 있어요.', '독성 정보가 없어요.', '/files/nongsaro_img/bb2cb880-d44b-490e-b414-748e404ec828.jpg', true, now(), now()),
(37, 'Pelargonium rosium', '모기풀', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '모기풀은 쥐손이풀과에 속하는 식물로, 주로 모기 퇴치용으로 사용돼요. 이집트가 원산지이며, 잎에서 나는 향이 모기를 쫓는 데 효과적이에요. 주로 봄과 여름에 분홍색과 흰색의 꽃을 피워요.', '모기풀은 독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/915fd832-057b-43d1-9403-3dfc5687c4a8.jpg', true, now(), now()),
(38, 'Guzmania lingulata', '구즈마니아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '구즈마니아는 파인애플과에 속하는 식물로 중앙 아메리카가 원산지예요. 이 식물은 만족이라는 꽃말을 가지고 있으며, 잎의 윗부분이 빨갛게 물들어 아름다움을 더해요. 주로 실내에서 기르기 적합하며, 습도가 높은 환경을 선호해요.', '구즈마니아는 독성이 없어요.', '/files/nongsaro_img/fa50b565-2b2d-4ac0-a6b8-a8e28ee213a1.jpg', true, now(), now()),
(39, 'Clivia miniata', '군자란', 'NORMAL', 'MEDIUM', 'NORMAL', false, '16~20℃', '군자란은 남아프리카의 나탈 지역이 원산지인 식물로, 수선화과에 속해요. 이 식물은 주로 실내에서 관상용으로 키우며, 꽃말은 고귀함을 의미해요. 군자란은 3년 이상 자라야 꽃을 피우며, 매년 봄과 여름에 화려한 꽃을 피워요.', '군자란은 복용 시 치명적인 독성을 가지고 있어요. 특히 어린이와 애완동물에게 주의가 필요해요.', '/files/nongsaro_img/9d553886-a681-4d91-b678-f50c086ae4d4.jpg', true, now(), now()),
(40, 'Glechoma hederacea ''Variegata''', '글레코마 헤데라케아', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '글레코마 헤데라케아는 유럽 원산의 덩굴성 식물로, 주로 지피식물로 사용돼요. 잎은 녹색과 연두색, 흰색, 크림색의 다양한 무늬를 가지고 있으며, 봄과 여름에 분홍색과 흰색의 꽃을 피워요. 관리가 쉬워 초보자도 키우기 좋으며, 실내에서 잘 자라요.', '독성 정보가 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/c1e31597-5af0-4d6a-8cbe-826eafe13218.jpg', true, now(), now()),
(41, 'Osmanthus fragrans', '금목서', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '금목서는 물푸레나무과에 속하는 상록 관목으로, 주로 중국이 원산지예요. 이 식물은 가을에 오렌지색, 노랑색, 흰색의 향기로운 꽃을 피우며, 생울타리로 적합해요. 꽃말은 유혹이며, 실내에서도 잘 자라는 특성이 있어요.', '독성 정보는 없어요.', '/files/nongsaro_img/c274c695-1b6b-47d5-9918-0a7397660d32.jpg', true, now(), now()),
(42, 'Euonymus japonicus', '사철나무', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '사철나무는 한국, 중국, 일본에 자생하는 관목형 식물이에요. 잎은 녹색, 연두색, 금색, 노란색의 다양한 색상을 가지고 있으며, 잎 가장자리에 무늬가 있어요. 초보자도 쉽게 키울 수 있는 식물로, 실내에서도 잘 자랍니다.', '사철나무는 일반적으로 독성이 없지만, 잎을 섭취하지 않도록 주의해 주세요.', '/files/nongsaro_img/6fa0d7be-a00a-4b7d-8475-18b433796741.jpg', true, now(), now()),
(43, 'Aucuba japonica var. variegata', '금목서', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '금목서는 층층나무과에 속하는 상록 관목으로, 주로 한국 남해안과 일본에서 자생해요. 잎은 광택이 있으며, 점무늬가 있어 화려한 외관을 자랑해요. 민간요법으로 나무껍질과 잎이 뱀독이나 종기, 화상 등에 사용되기도 해요.', '독성은 없으나, 민간요법으로 사용될 수 있어요.', '/files/nongsaro_img/874fbfb3-377d-4bcd-b05a-8f81513fd75c.gif', true, now(), now()),
(44, 'Zamioculcas zamiifolia', '자미오쿨카스', 'NORMAL', 'MEDIUM', 'EASY', false, '16~20℃', '자미오쿨카스는 아프리카 동부와 남부가 원산지인 식물로, 실내에서 잘 자라는 특성이 있어 인기가 많아요. 이 식물은 그늘진 곳에서도 잘 견디지만, 밝은 간접광에서 더 잘 자랍니다. 과습에 주의해야 하며, 저온 상태에서는 뿌리가 썩기 쉬워요.', '자미오쿨카스를 섭취하면 치명적인 독성을 유발할 수 있어요. 특히 어린이와 반려동물에게 주의가 필요합니다.', '/files/nongsaro_img/30aba53e-fe96-453d-a1d0-ae4484a1a23e.jpg', true, now(), now()),
(45, 'Dracaena sanderiana [금천죽]', '금천죽', 'NORMAL', 'LOW', 'EASY', false, '16~20℃', '금천죽은 아프리카 카메룬이 원산지인 백합과 식물로, 주로 실내에서 관상용으로 많이 기르며 초보자도 쉽게 관리할 수 있어요. 이 식물은 포름알데히드, 벤젠, 톨루엔 등 유해 물질을 제거하는 공기정화 능력이 뛰어나요. 성장 속도는 느리지만, 적절한 환경에서 잘 자라며 잎의 광택이 있어 실내 장식에 적합해요.', '금천죽은 독성을 가지고 있어 어린이와 애완동물의 접근을 피해야 하며, 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/dc7893ee-f848-4826-aa21-11751da369c2.jpg', true, now(), now()),
(46, 'Gynura aurantiaca', '뿔우단풀', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '뿔우단풀은 국화과에 속하는 식물로, 자바와 멜라네시아 원산의 원예 품종이에요. 주로 실내에서 관상용으로 키우며, 보랏빛 잎이 특징적이에요. 관리가 비교적 쉬운 편이지만 적절한 환경을 제공해야 건강하게 자랄 수 있어요.', '독성 정보는 없지만, 어린이와 반려동물이 먹지 않도록 주의하세요.', '/files/nongsaro_img/04e04c7e-1c6b-414e-b952-55989f04250f.jpg', true, now(), now()),
(47, 'Begonia semperflorens', '베고니아', 'FREQUENT', 'HIGH', 'NORMAL', true, '21~25℃', '베고니아는 브라질 원산의 식물로, 1년 내내 꽃을 피워내는 귀한 식물이에요. 잎은 화려하고 광택이 있으며, 다양한 색상의 꽃을 피워 실내외 화단에 적합해요. 생장 속도가 빨라 통풍에 주의해야 해요.', '베고니아는 일반적으로 독성이 없어요.', '/files/nongsaro_img/5a2966b2-5ab4-4d6f-a368-561fa3f04a01.jpg', true, now(), now()),
(48, 'Podocarpus macrophyllus', '나한송', 'NORMAL', 'MEDIUM', 'EASY', false, '10~15℃', '나한송은 중국과 일본이 원산지인 상록 관목으로, 잎이 반질거리고 섬세한 질감을 가지고 있어 실내 장식용으로 인기가 많아요. 공기 정화 효과가 뛰어나며, 음지에서도 잘 자라는 특성이 있어 관리가 용이해요. 성장 속도는 느리지만, 실내의 불량한 환경에도 잘 견딥니다.', '나한송은 독성이 있어 섭취 시 구토, 설사 등의 증상을 유발할 수 있어요. 반려동물과 어린이의 손이 닿지 않는 곳에 두는 것이 안전해요.', '/files/nongsaro_img/9eef55dd-356d-4dfe-bf8f-3e613a12569e.jpg', true, now(), now()),
(49, 'Nandina domestica', '남천', 'NORMAL', 'HIGH', 'EASY', false, '16~20℃', '남천은 매자나무과에 속하는 상록 관목으로, 한국, 일본, 중국 남부가 원산지예요. 이 식물은 꽃, 열매, 잎, 단풍이 모두 아름다워 실내의 동양적인 분위기에 잘 어울려요. 성숙한 열매는 남천실이라 하며 해수, 천식, 백일해, 간기능장애 등에 약제로 사용돼요.', '남천의 열매와 잎에는 독성이 있어, 섭취 시 구토, 설사 등의 증상이 나타날 수 있어요.', '/files/nongsaro_img/b5af129b-bbd2-4d94-8758-348fddfeec83.jpg', true, now(), now()),
(50, 'Nematanthus gregarius', '네마탄서스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '네마탄서스는 브라질 원산의 식물로, 주로 관목형과 덩굴성으로 자랍니다. 이 식물은 빨강색과 오렌지색의 화려한 꽃을 피우며, 잎은 광택이 있고 질감이 거칩니다. 주로 컨테이너나 공중걸이로 키우기 적합합니다.', '독성 정보는 없습니다.', '/files/nongsaro_img/254ec7a3-3541-4347-bdb0-cb46d4dfefc3.jpg', true, now(), now()),
(51, 'Neoregelia carolinae', '네오레겔리아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '네오레겔리아는 브라질의 열대 우림에 자생하는 착생형 식물이에요. 이 식물은 로제트형의 잎을 가지고 있으며, 꽃이 필 때 중심부가 붉게 물들어요. 꽃이 핀 후 로제트는 죽고, 새로운 자구를 형성하여 번식해요.', '특별한 독성은 없지만, 잎의 가시에 주의해야 해요.', '/files/nongsaro_img/2a9b5cdc-d494-4fea-a06e-5df080003760.jpg', true, now(), now()),
(52, 'Senecio rowleyanus', '콩선인장', 'INFREQUENT', 'MEDIUM', 'NORMAL', false, '16~20℃', '콩선인장은 덩굴성 다육식물로, 잎이 염주구슬처럼 생겼어요. 작고 하얀 꽃이 사계절 내내 피며, 파란 콩 모양의 잎과 함께 귀여운 모습을 자랑해요. 건조에 강하며, 실내 걸이용 화분으로 인기가 많아요.', '복용 시 치명적인 독성을 나타낼 수 있으니 주의가 필요해요.', '/files/nongsaro_img/902f5ae4-8ea7-4881-a446-aab549f199cd.jpg', true, now(), now()),
(53, 'Impatiens hybrid ''New Guinea''', '뉴기니임파첸스', 'FREQUENT', 'MEDIUM', 'EASY', true, '21~25℃', '뉴기니임파첸스는 열대성 작물로 추위에 약한 다년생 초본입니다. 일반적으로 30~60cm까지 자라며, 다양한 색상의 꽃을 피웁니다. 반그늘에서도 잘 자라며, 여름철 내내 꽃을 감상할 수 있어요.', '독성은 없으나 섭취하지 않도록 주의하세요.', '/files/nongsaro_img/44bf050e-369f-4b8b-97cb-14b1a8ff33c7.jpg', true, now(), now()),
(54, 'Ficus retusa', '대만고무나무', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '대만고무나무는 뽕나무과에 속하는 상록 교목으로, 주로 중국 남부와 인도 등지에서 자생해요. 이 식물은 실내에서 1.2~1.8m 정도까지 자라며, 잎은 5~10cm 정도로 비후하고 광택이 있어요. 환경 변화에 민감하여 서서히 적응시켜야 하며, 줄기에는 기근이 발생할 수 있어요.', '대만고무나무는 독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/c2ab49d9-3f4b-4c97-ba2b-d2eb90455101.jpg', true, now(), now()),
(55, 'Nephrolepis cordifolia ''Duffii''', '더피고사리', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '16~20℃', '더피고사리는 뉴질랜드 원산의 양치류로, 습한 환경을 좋아해요. 생장기에는 물이 부족하지 않도록 관리해야 하며, 수분이 부족하면 잎끝이 상할 수 있어요. 여름철 청량감을 주는 외형으로 그린인테리어에 많이 활용돼요.', '더피고사리는 독성이 없어요.', '/files/nongsaro_img/f0714135-4eda-4e84-8c36-50aaffe08828.jpg', true, now(), now()),
(56, 'Beaucarnea recurvata', '덕구리난', 'NORMAL', 'HIGH', 'EASY', true, '21~25℃', '덕구리난은 멕시코 원산의 식물로, 줄기 밑둥에 물을 저장하여 술병처럼 부푼 모양을 하고 있어 술병난이라고도 불려요. 이 식물은 주로 실내에서 관상용으로 키우며, 관리가 쉬워 초보자에게 적합해요. 덕구리난은 건조한 환경을 좋아하며, 과습 시 줄기가 물러질 수 있으니 주의해야 해요.', '독성은 없어요.', '/files/nongsaro_img/bb259872-bc77-4cfa-91cf-6116695bfb4e.jpg', true, now(), now()),
(57, 'Ficus elastica var. decora', '데코라 고무나무', 'NORMAL', 'MEDIUM', 'EASY', false, '21~25℃', '데코라 고무나무는 열대 아시아 원산의 원예품종으로, 붉은 빛이 도는 짙은 녹색 잎을 가지고 있어요. 잎과 줄기를 자르면 흰 즙이 나오며, 꽃은 6∼7월에 잎겨드랑이에 핍니다. 수액은 피부나 점막을 자극할 수 있으니 주의가 필요해요.', '수액이 피부나 점막을 자극할 수 있으니, 접촉을 피하고 주의해야 해요.', '/files/nongsaro_img/0887e55f-2001-4517-9006-8bc30570c474.jpg', true, now(), now()),
(58, 'Dendrobium phalaenopsis', '덴파레', 'INFREQUENT', 'HIGH', 'NORMAL', true, '21~25℃', '덴파레는 난초과에 속하는 식물로, 인도네시아와 파푸아뉴기니가 원산지예요. 이 식물은 다양한 색상의 꽃을 피우며, 주로 실내에서 관상용으로 키워요. 관리 난이도는 경험자 수준으로, 적절한 환경에서 잘 자라요.', '덴파레는 독성이 없어요.', '/files/nongsaro_img/5a71e702-4525-4b2c-af71-62a256c1361b.jpg', true, now(), now()),
(59, 'Cyrtomium falcatum', '도깨비고비', 'FREQUENT', 'LOW', 'EASY', true, '16~20℃', '도깨비고비는 바닷가와 섬의 저지대의 바위틈에서 자라는 식물이에요. 상록성으로서 짧고 굵은 뿌리를 가지며, 잎은 겹잎으로 끝이 갑자기 뾰족해져요. 포자낭군은 잎 뒷면 전체에 붙으며 성숙하면 중앙부가 흑갈색으로 변해요.', '도깨비고비는 독성이 없어요.', '/files/nongsaro_img/bcb3a2f4-508d-41b4-92c6-41fe7baaf649.jpg', true, now(), now()),
(60, 'Camellia japonica', '동백', 'NORMAL', 'HIGH', 'NORMAL', true, '16~20℃', '동백은 상록 활엽소 교목으로 한국 남해안, 일본, 중국에 자생해요. 꽃은 12월부터 4월까지 피고, 결실기는 가을이에요. 잎은 타원형이며, 꽃의 열매는 붉은색이 돌아요.', '동백은 독성이 없어요.', '/files/nongsaro_img/59738740-cc62-42a2-83ab-6a75a050dc85.jpg', true, now(), now()),
(61, 'Polyscias balfouriana', '둥근잎 아랄리아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '둥근잎 아랄리아는 동양적인 이미지가 강한 관엽식물로, 무늬가 있는 잎과 없는 잎 모두 매력적이에요. 이 식물은 키우기가 쉽지 않으며, 환경이 맞지 않으면 잎이 쉽게 떨어질 수 있어요. 특히 습도 조절이 중요하며, 자주 잎에 분무해 주는 것이 좋아요.', '독성 정보가 없어요.', '/files/nongsaro_img/27157f8f-3165-43aa-89f9-dbb46e1ebae5.jpg', true, now(), now()),
(62, 'Duranta erecta', '듀란타', 'NORMAL', 'HIGH', 'NORMAL', true, '21~25℃', '듀란타는 마편초과에 속하는 관목형 식물로, 주로 브라질이 원산지예요. 강한 향기를 가지고 있으며, 보라색 꽃을 피우고 금색 열매를 맺어요. 실내에서는 높은 광도와 적절한 습도를 유지하면 잘 자랍니다.', '듀란타는 일반적으로 독성이 없어요.', '/files/nongsaro_img/e886227f-5b07-4748-8938-dbbaecd4cb2d.jpg', true, now(), now()),
(63, 'Dracaena reflexa ''Song of Jamaica''', '드라세나 송오브자마이카', 'NORMAL', 'LOW', 'EASY', true, '16~20℃', '드라세나 송오브자마이카는 아프리카가 원산지인 백합과 식물로, 실내에서 인기가 많아요. 이 식물은 내음성이 강하고, 실내의 밝은 장소에서 잘 자라며, 너무 어두운 곳에서는 광량 부족으로 줄기가 웃자라거나 잎이 떨어질 수 있어요. 줄기와 잎이 부드러운 느낌을 주며, 2년에 한 번 정도 분갈이를 해주는 것이 좋습니다.', '드라세나 송오브자마이카는 독성이 없어요.', '/files/nongsaro_img/76085387-4581-46dc-b9f4-e5127b1f186d.jpg', true, now(), now()),
(64, 'Dracaena reflexa', '송오브인디아', 'FREQUENT', 'LOW', 'EASY', true, '16~20℃', '송오브인디아는 번영과 영광을 상징하는 식물로, 다양한 크기와 무늬를 가진 품종이에요. 반음지 식물로 직사광선을 피하고 추위에 약해 겨울에는 따뜻하게 관리해야 해요. 실내조경에 자주 사용되며 일반 가정에서도 인기가 많아요.', '송오브인디아는 독성이 없어요.', '/files/nongsaro_img/7f2cc20d-862f-458b-b18a-7df662bca51e.gif', true, now(), now()),
(65, 'Dracaena angustifolia ''Java''', '드라세나 자바', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '드라세나 자바는 반음지성 식물로, 통풍이 좋은 밝은 그늘에서 잘 자라요. 공기정화 능력이 뛰어나며, 증산작용을 통해 주변 공기의 수분과 유해 물질을 흡수해요. 환경이 좋지 않은 장소에서도 잘 자라며, 푸른 잎이 풍성하게 자라 멋진 수형을 감상할 수 있어요.', '드라세나 자바는 독성이 없어요.', '/files/nongsaro_img/f9063ef2-3b00-4b77-a788-494a2ff60e52.jpg', true, now(), now()),
(66, 'Dracaena deremensis ''Virens Compacta''', '콤팩타', 'NORMAL', 'LOW', 'EASY', false, '16~20℃', '콤팩타는 실내에서 키우기 좋은 식물로, 여름철에는 직사광선을 피해야 해요. 잎은 짙은 암녹색이며, 나선형으로 줄기에서 촘촘하게 나와요. 공기정화 능력이 뛰어나 포름알데히드, 벤젠, 톨루엔 등을 제거해요.', '애완동물에게 해로울 수 있어 주의가 필요해요.', '/files/nongsaro_img/c242176d-e34e-43c4-b702-2d85b353a6fc.jpg', true, now(), now()),
(67, 'Dracaena concinna ''Tricolor Rainbow''', '드라세나 트리컬러 레인보우', 'FREQUENT', 'MEDIUM', 'EASY', true, '16~20℃', '드라세나 트리컬러 레인보우는 줄기가 가늘고 키는 3~4m까지 자라며, 잎의 폭은 1~2cm, 길이는 30~60cm입니다. 잎 가장자리는 적색이며, 안쪽은 유백색으로 붉은빛을 띠고 있습니다. 고온다습한 환경을 좋아하며, 내음성이 강해 실내에서 잘 자랍니다.', '독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/7a089830-0009-4bdf-b3d3-53813a836ba1.jpg', true, now(), now()),
(68, 'Dracaena draco', '드라코', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '드라세나 드라코는 자연 서식지에서는 거목으로 자라지만, 실내에서는 최대 1미터까지 자랍니다. 충분한 빛을 받으면 잎 가장자리에 붉은색을 띠며, 오래된 잎은 아래쪽으로 아치형을 그립니다. 산소와 음이온을 많이 내뿜어 공기정화 효과가 뛰어납니다.', '드라코는 애완동물에게 해로울 수 있습니다. 섭취 시 구토나 설사를 유발할 수 있습니다.', '/files/nongsaro_img/e1a2b2ae-aac2-4b5c-a1ad-9a70e181e002.jpg', true, now(), now()),
(69, 'Dracaena sanderiana [드라세나 산데리아나]', '드라세나 산데리아나', 'FREQUENT', 'LOW', 'EASY', false, '21~25℃', '드라세나 산데리아나는 서아프리카의 카메룬이 원산지인 식물로, 주로 실내에서 관상용으로 키워져요. 이 식물은 포름알데히드, 벤젠, 톨루엔 등의 공기 오염 물질을 제거하는 데 효과적이에요. 애완동물에게는 독성이 있으므로 주의가 필요해요.', '드라세나 산데리아나는 애완동물에게 독성이 있어요. 섭취 시 구토나 설사를 유발할 수 있어요.', '/files/nongsaro_img/b7b72162-320e-4d3d-b943-48a765c22511.gif', true, now(), now()),
(70, 'Dracaena sanderiana [세레스 드라세나]', '세레스 드라세나', 'FREQUENT', 'LOW', 'EASY', true, '16~20℃', '세레스 드라세나는 백합과에 속하는 식물로, 아프리카가 원산지예요. 이 식물은 폭이 좁고 가는 잎을 가지며, 실내에서 잘 자라요. 관리가 쉬워 초보자에게 적합한 식물이에요.', '독성이 없어 반려동물에게 안전해요.', '/files/nongsaro_img/7af3514a-a2fe-48cb-a879-223e7f1b94a8.jpg', true, now(), now()),
(71, 'Dracaena surculosa', '드라세나 수르쿨로사', 'NORMAL', 'LOW', 'NORMAL', true, '16~20℃', '드라세나 수르쿨로사는 60~90cm 정도 자라며, 줄기는 작지만 강하고 잎은 타원형으로 양 끝이 뾰족해요. 잎의 반점에 따라 플로리다 뷰티, 밀키웨이 등으로 나뉘며, 표면은 녹색으로 반들반들하고 불규칙한 흰 반점이 있어요. 꽃은 흰색으로 얇은 꽃줄기와 함께 복산형 꽃차례로 작은 꽃이 둥글게 모여 피고 향기가 좋아요.', '독성이 없어요.', '/files/nongsaro_img/c6dbc827-cf61-42ff-8834-c7c1ad74e9dd.jpg', true, now(), now()),
(72, 'Dieffenbachia ''Marianne''', '마리안느', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '마리안느는 부드러운 연녹색 잎의 중앙에 선명한 흰색 무늬가 있는 소형종이에요. 이 식물은 빛이 적고 따뜻한 실내에서 잘 자라며, 추위에 매우 약해요. 수액이 피부에 닿으면 알레르기와 가려움증을 유발할 수 있으니 주의해야 해요.', '수액이 피부에 닿으면 알레르기와 가려움증을 유발할 수 있어요. 어린이와 반려동물의 손이 닿지 않는 곳에 두는 것이 좋아요.', '/files/nongsaro_img/d664aec3-3ad5-4cc2-8657-3b5ff6c10377.gif', true, now(), now()),
(73, 'Dieffenbachia amoena ''Tropic snow''', '디펜바키아', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '디펜바키아는 열대 아메리카가 원산지인 실내 관엽식물로, 잎은 두껍고 넓으며 유백색의 불규칙한 반점 무늬가 있습니다. 생육이 강건하며, 내한력이 약해 실내에서 키우기 적합합니다. 식물 전체에 독성이 있어 섭취 시 심한 통증과 마비 증상을 일으킬 수 있습니다.', '식물의 수액이 피부에 닿으면 알레르기를 유발할 수 있으며, 섭취 시 심한 통증과 마비 증상을 일으킬 수 있습니다.', '/files/nongsaro_img/50793b25-015f-471a-a2b3-04603703f121.jpg', true, now(), now()),
(74, 'Ficus lyrata', '떡갈잎고무나무', 'NORMAL', 'MEDIUM', 'EASY', false, '16~20℃', '떡갈잎고무나무는 서아프리카가 원산지인 식물로, 큰 잎과 강한 생명력으로 인기가 많아요. 잎은 평균 30cm 정도로 두껍고, 광택이 있으며 바이올린 모양을 닮았어요. 과습 시 잎이 검게 변해 떨어질 수 있으니 주의가 필요해요.', '떡갈잎고무나무는 식물체 전체에 독성이 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/fc5f1fcf-2905-4b5a-9cd9-fb383aa3a672.jpg', true, now(), now()),
(75, 'Ceropegia woodii', '러브체인', 'INFREQUENT', 'MEDIUM', 'NORMAL', true, '16~20℃', '러브체인은 박주가리과에 속하는 덩굴성 식물로, 심장 모양의 잎이 특징이에요. 이 식물은 건조에 강하고, 여름철에 분홍색 깔때기 모양의 독특한 꽃을 피워요. 주로 줄기 삽목으로 번식하며, 덩굴을 잘라서 땅에 꽂으면 쉽게 자라요.', '독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/efe531e0-d059-4316-9785-5a2d8bad518e.jpg', true, now(), now()),
(76, 'Begonia rex', '렉스베고니아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '렉스베고니아는 잎의 무늬가 아름다워 관상용으로 인기가 많아요. 잎은 두텁고 얼룩무늬가 있으며, 다양한 색상과 패턴을 자랑해요. 벤치 아래, 시원하고 습한 그늘에서 가장 잘 자라요.', '렉스베고니아는 독성이 없어요.', '/files/nongsaro_img/a626c08d-a296-458d-be4d-b972a5c9952a.jpg', true, now(), now()),
(77, 'Rumohra adiantiformis', '루모라고사리', 'FREQUENT', 'MEDIUM', 'HARD', true, '16~20℃', '루모라고사리는 남아프리카가 원산지인 고란초과의 식물이에요. 주로 실내식물로 사용되며, 넓은 삼각형 비늘잎이 특징이에요. 포자번식으로 봄에 번식하며, 관리가 까다로운 편이에요.', '루모라고사리는 독성이 없어요.', '/files/nongsaro_img/bb12379b-6f47-453e-811b-77932372ea9c.jpg', true, now(), now()),
(78, 'Ruscus spp.', '루스커스', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '루스커스는 지중해와 아프리카가 원산지인 백합과 식물이에요. 주로 관목형으로 성장하며, 엽첨과 엽각이 뾰족한 작은 잎을 가지고 있어요. 관리가 쉬워 초보자도 키우기 적합해요.', '루스커스는 독성이 없는 식물로 알려져 있어요.', '/files/nongsaro_img/b8431c04-3d08-4a37-adc5-57569af900ac.jpg', true, now(), now()),
(79, 'Maranta leuconeura', '마란타', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '마란타는 중앙 아메리카와 브라질 원산의 식물로, 잎의 독특한 무늬와 기도하는 듯한 잎의 움직임으로 유명해요. 이 식물은 따뜻하고 습한 환경에서 잘 자라며, 낮에는 잎이 옆으로 펴졌다가 밤이 되면 위로 접히는 특징이 있어요. 건조하고 추운 환경에서는 잎이 갈색으로 변할 수 있으므로 습도 유지에 주의해야 해요.', '마란타는 일반적으로 독성이 없어요.', '/files/nongsaro_img/55f25a64-20d5-4c73-88b5-6f053deb064a.jpg', true, now(), now()),
(80, 'Rohdea japonica', '만년청', 'NORMAL', 'LOW', 'EASY', false, '21~25℃', '만년청은 내한성 상록 다년초로, 굵은 땅속줄기 끝에서 9~12장의 녹색 잎이 모여납니다. 꽃은 5~7월에 연한 노란색이나 흰색으로 피며, 열매는 8월에 붉게 익습니다. 근경에는 로데인(Rohdein)이 들어 있어 강심제와 이뇨제로 악용될 수 있습니다.', '근경에 로데인(Rohdein)이 들어 있어 강심제와 이뇨제로 악용될 수 있습니다. 섭취 시 주의가 필요합니다.', '/files/nongsaro_img/37fd2ef3-f1a9-4e24-be6a-eee0283992ba.jpg', true, now(), now()),
(81, 'Mandevilla sanderi', '만데빌라', 'NORMAL', 'MEDIUM', 'NORMAL', false, '16~20℃', '만데빌라는 브라질 원산의 덩굴식물로, 화려한 꽃과 은은한 향기를 지니고 있어요. 주로 컨테이너나 행잉바스켓에 심어 실내에서 기르며, 약간 건조하게 관리하는 것이 좋아요. 꽃은 봄부터 가을까지 피며 다양한 색상으로 눈길을 끌어요.', '만데빌라는 강한 독성을 가지고 있어 식용하면 안 돼요. 섭취 시 구토, 설사 등의 증상이 나타날 수 있어요.', '/files/nongsaro_img/55aebe90-cd82-42fd-b616-97ac4bcc5e39.jpg', true, now(), now()),
(82, 'Zamia pumila', '멕시코소철', 'NORMAL', 'MEDIUM', 'EASY', false, '21~25℃', '멕시코소철은 소철과에 속하는 식물로, 주로 멕시코, 자마이카, 콜롬비아 등지에서 자생해요. 이 식물은 열대 및 아열대 지역에서 약 40종이 분포하며, 주로 관엽식물로 재배돼요. 잎은 골판지처럼 딱딱하고 이국적인 모습을 연출하는 데 이용돼요.', '멕시코소철의 열매는 식용하면 안 되며, 섭취 시 복통이나 메스꺼움을 유발할 수 있어요.', '/files/nongsaro_img/64ac579d-ab99-4f40-8c57-fe15eb297b02.jpg', true, now(), now()),
(83, 'Ficus elastica ''Robusta''', '멜라니 고무나무', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '멜라니 고무나무는 인도와 말레이시아가 원산지인 실내 식물로, 두껍고 광택이 있는 큰 타원형의 잎을 가지고 있어요. 이 식물은 음이온과 산소를 많이 발생시키며, 실내 공기 정화에 도움을 줘요. 새로 나오는 잎은 붉은빛을 띠다가 점차 짙은 녹색으로 변하는 특징이 있어요.', '멜라니 고무나무는 라텍스를 포함하고 있어 피부에 닿으면 알레르기 반응을 일으킬 수 있어요. 섭취 시 소화 장애를 유발할 수 있으니 주의해야 해요.', '/files/nongsaro_img/b9dd4766-71ca-4309-9f79-28b9dc086f74.jpg', true, now(), now()),
(84, 'Begonia lucerna', '목베고니아', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '목베고니아는 프랑스의 식물 애호가 베공의 이름에서 유래되었어요. 이 식물은 높이가 60cm 정도로 자라며, 잎은 가름한 심장 모양이고 전체가 녹색이며 흰 얼룩점이 드문드문 있어요. 줄기는 곧게 자라며 어긋나게 자라는 커다란 잎과 풍성하게 꽃을 피우는 품종이에요.', '독성이 없어요.', '/files/nongsaro_img/d282f874-4a38-47d8-b3ab-9bd70582d024.jpg', true, now(), now()),
(85, 'Monstera deliciosa', '몬스테라', 'FREQUENT', 'MEDIUM', 'EASY', false, '16~20℃', '몬스테라는 덩굴성 대형관엽식물로 6~8m까지 자라요. 잎은 진녹색으로 크고 광택이 나며, 잎맥 사이에 타원형의 구멍이 있어 폭우나 강한 바람에도 견딜 수 있는 구조로 발달됐어요. 흰색의 꽃이 피고 열매도 달리며, 잎은 절엽으로 하여 꽃꽂이 재료로도 쓰여요.', '몬스테라는 식물체에 독성이 있어 어린이 주변에 두지 않는 것이 좋아요. 섭취 시 구토, 설사 등의 증상이 나타날 수 있어요.', '/files/nongsaro_img/b8b704ab-f6e9-45f2-82ae-fe2e7de57558.jpg', true, now(), now()),
(86, 'Rhapis excelsa ''Variegata''', '무늬관음죽', 'NORMAL', 'MEDIUM', 'NORMAL', false, '16~20℃', '무늬관음죽은 야자과에 속하는 식물로, 주로 실내에서 관상용으로 기르기 적합해요. 손바닥 모양의 겹잎을 가지며, 그늘과 추위에 강해 관리가 쉬운 편이에요. 공기정화 능력이 뛰어나 포름알데히드, 벤젠 등을 제거하는 데 효과적이에요.', '수액이 피부나 점막을 자극할 수 있으니 주의하세요. 특히 어린이와 애완동물의 접근을 피하는 것이 좋아요.', '/files/nongsaro_img/388ffed5-4797-4e07-ab29-c3ce15757403.jpg', true, now(), now()),
(87, 'Trachelospermum asiaticum var. variegatum', '무늬마삭줄', 'FREQUENT', 'MEDIUM', 'EASY', true, '16~20℃', '무늬마삭줄은 협죽도과에 속하는 덩굴성 식물로, 주로 한국, 일본, 아시아에서 자생해요. 잎은 타원형으로 광택이 있으며, 꽃은 5~6월에 노란색과 흰색으로 피어요. 열매는 길이 1.2~2.2cm로 두 개씩 달려 있어요.', '무늬마삭줄은 독성이 없어요.', '/files/nongsaro_img/499a39ba-918e-4f44-bbab-013c7142607a.jpg', true, now(), now()),
(88, 'Ficus benjamina ''Variegata''', '무늬벤자민고무나무', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '무늬벤자민고무나무는 뽕나무과에 속하며, 주로 실내에서 기르는 관엽식물이에요. 이 식물은 포름알데히드, 벤젠, 톨루엔, 크실렌, 클로로포름 같은 유해 물질을 제거하는 공기정화 능력이 있어요. 잎이 작고 성장함에 따라 가지가 우아하게 늘어지며, 건조한 환경에도 강한 편이에요.', '무늬벤자민고무나무는 독성이 거의 없지만, 잎을 섭취하지 않도록 주의하세요.', '/files/nongsaro_img/a69a0b89-4a02-4ffa-819b-152edf8d3e92.jpg', true, now(), now()),
(89, 'Ardisia pusilla ''Variegata''', '무늬산호수', 'NORMAL', 'MEDIUM', 'EASY', false, '21~25℃', '무늬산호수는 자금우과에 속하는 식물로, 한국, 중국, 일본에서 자생합니다. 이 식물은 반양지성으로 밝은 실내나 오전 햇빛이 드는 곳에서 잘 자라며, 한낮의 직사광선에는 잎이 화상을 입을 수 있어 주의가 필요해요. 무늬산호수는 약용으로도 사용되며, 물 관리가 중요해요.', '무늬산호수는 섭취하면 안 되며, 섭취 시 위장 장애를 일으킬 수 있어요.', '/files/nongsaro_img/7dbbdbae-2b9f-4c59-8346-a80a26eaf039.jpg', true, now(), now()),
(90, 'Acorus gramineus var. variegatus', '무늬석창포', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '무늬석창포는 천남성과에 속하며 아시아와 일본이 원산지예요. 습지나 테두리, 지피식물로 적합하며 수경식재로도 잘 자라요. 관리가 쉬워 초보자에게 적합한 식물이에요.', '무늬석창포는 독성이 없어요.', '/files/nongsaro_img/f73aedb9-066e-406c-9f58-3ea6877a3efe.jpg', true, now(), now()),
(91, 'Schefflera arboricola ''Hong Kong Variegata''', '무늬쉐플레라 홍콩', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '무늬쉐플레라 홍콩은 동남아시아 자생종의 원예품종으로, 실내 식재에 적합한 식물이에요. 손바닥 모양의 넓은 타원형 잎을 가지며, 공기정화 능력이 있어 실내 공기질 개선에 도움을 줄 수 있어요. 관리가 쉬워 초보자도 키우기 좋으며, 다양한 환경에서 잘 자라요.', '무늬쉐플레라 홍콩은 독성이 없어요.', '/files/nongsaro_img/7217ec03-3e33-4757-953a-484c22c468b3.jpg', true, now(), now()),
(92, 'Alpinia zerumbet ''Variegata''', '알피니아 제룸벳', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '알피니아 제룸벳은 생강과에 속하는 식물로, 주로 솔로몬군도에서 자생해요. 이 식물은 줄무늬가 있는 잎과 오렌지색, 흰색의 혼합된 꽃을 피워요. 실내에서 키우기 쉬운 식물로, 공기 정화 능력이 뛰어나요.', '알피니아 제룸벳은 독성이 없어 안전해요.', '/files/nongsaro_img/5b6e1478-b92e-489c-9266-3e2bdaaf61cf.jpg', true, now(), now()),
(93, 'Yucca elephantipes ''Variegata''', '무늬유카', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '무늬유카는 중앙아메리카 원산의 실내식물로, 백합과에 속해요. 잎은 가죽 질감에 가장자리가 거칠고 줄기 끝이 연한 특징이 있어요. 주간이 있는 나무로 진녹색 잎이 노란색과 금색의 줄무늬를 가지고 있어요.', '무늬유카는 독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/e46cf694-7492-4cc5-9cf2-2e209a9b8658.jpg', true, now(), now()),
(94, 'Chlorophytum comosum var. variegatum', '무늬접란', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '무늬접란은 남아프리카가 원산지인 백합과 식물로, 가늘고 긴 잎에 줄무늬가 있는 것이 특징이에요. 주로 컨테이너, 지피식물, 행잉바스켓 등으로 활용되며, 실내에서 키우기 쉬운 식물이에요. 공기정화 능력이 뛰어나며, 초보자도 쉽게 관리할 수 있어요.', '무늬접란은 독성이 없어 반려동물에게도 안전해요.', '/files/nongsaro_img/d89c4a58-bd20-4d06-b06e-8a9a5696565d.jpg', true, now(), now()),
(95, 'Farfugium japonicum ''Argenteum''', '무늬털머위', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '무늬털머위는 국화과에 속하는 식물로, 주로 한국 남해안, 일본, 대만, 중국에서 발견되는 변종이에요. 이 식물은 두껍고 신장 모양의 광택 있는 잎을 가지며, 여름과 가을에 노란색 꽃을 피워요. 실내 식물로도 적합하며, 습지나 컨테이너에서도 잘 자라요.', '무늬털머위는 독성이 없어서 안전해요.', '/files/nongsaro_img/9fb9b64b-87f1-4a98-80fc-49a795fc8a55.jpg', true, now(), now()),
(96, 'Fatshedera lizei ''Variegata''', '무늬팻츠헤데라', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '무늬팻츠헤데라는 벤젠 제거에 효과적인 에코플랜트로 알려져 있어요. 키는 30-40cm 정도로 작고 줄기는 곧게 자랍니다. 두릅나무과에 속하며, 원예속간 교배종으로 실내에서 기르기 적합해요.', '무늬팻츠헤데라는 독성이 없어요.', '/files/nongsaro_img/c36d4622-9368-4eae-83a0-dbc2aa7f9d30.jpg', true, now(), now()),
(97, 'Ficus pumila ''Variegata''', '무늬아이비', 'NORMAL', 'LOW', 'NORMAL', true, '21~25℃', '무늬아이비는 뽕나무과에 속하는 덩굴성 식물로, 한국, 일본, 중국 남부가 원산지예요. 이 식물은 높은 습도를 좋아하며, 실내에서 잘 자라지만 매년 봄에 분갈이를 해주는 것이 좋아요. 잎 가장자리에 무늬가 있어 장식용으로 인기가 많아요.', '독성 정보가 없어요.', '/files/nongsaro_img/d9472922-bfd7-4cba-8053-829327f2561c.jpg', true, now(), now()),
(98, 'Muehlenbeckia complexa', '트리안', 'NORMAL', 'LOW', 'EASY', true, '16~20℃', '트리안은 뉴질랜드와 호주가 원산지인 덩굴성 관엽식물이에요. 실내 밝은 장소에서 잘 자라며, 직사광선만 피하면 건강하게 키울 수 있어요. 번식력이 왕성하여 자주 정리해 주는 것이 좋습니다.', '트리안은 독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/1e007dd4-983d-4afa-b895-c96322d95589.jpg', true, now(), now()),
(99, 'Saxifraga stolonifera', '바위취', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '바위취는 우리나라 중부 이남의 반음지와 음지에서 조경용으로 식재되는 상록 다년생 초본이에요. 잎은 녹색에 연한 무늬가 있으며, 뒷면은 자줏빛이 도는 붉은색을 띠고 있어요. 꽃은 백색으로 꽃자루의 높이는 20~40㎝에 달하며, 열매는 7~8월경에 달려요.', '독성은 없으나, 섭취는 피하는 것이 좋아요.', '/files/nongsaro_img/ee60c2b9-e6d4-4914-a005-41c9f4846c49.jpg', true, now(), now()),
(100, 'Platycerium bifurcatum', '플라티케리움', 'FREQUENT', 'MEDIUM', 'HARD', true, '16~20℃', '플라티케리움은 고사리과에 속하는 식물로, 주로 오스트레일리아가 원산지입니다. 이 식물은 사슴뿔 모양의 잎을 가지고 있으며, 잎 표면은 회녹색이고 뒷면은 녹백색입니다. 밝은 곳을 좋아하며, 습한 환경에서 잘 자랍니다.', '독성은 없으나, 어린아이와 반려동물이 섭취하지 않도록 주의해 주세요.', '/files/nongsaro_img/01124c07-0625-4f73-9e5c-b90d6c6e01aa.jpg', true, now(), now()),
(101, 'Farfugium japonicum', '반딧불털머위', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '반딧불털머위는 국화과의 여러해살이풀로, 주로 남부지방이나 울릉도, 제주도의 바닷가에서 자라요. 이 식물은 늘 푸른 잎을 가지고 있으며, 9월에서 10월 사이에 노란색 꽃이 피어요. 한방과 민간에서 진통, 보익, 진정 등의 약재로 사용되며, 관상용으로도 많이 심어요.', '독성은 없으나, 섭취하지 않는 것이 좋아요.', '/files/nongsaro_img/d127cbd2-8975-4bfb-97fe-3a14e70e57fd.jpg', true, now(), now()),
(102, 'Ardisia crenata', '자금우', 'NORMAL', 'LOW', 'NORMAL', true, '16~20℃', '자금우는 한국, 중국, 인도, 말레이시아가 원산지인 관목형 식물이에요. 주로 실내에서 키우기 적합하며, 부식질이 풍부한 토양과 약간 응달진 장소에서 잘 자라요. 흰색 꽃을 피우고 빨강색, 노랑색, 흰색의 열매를 맺어요.', '독성 정보가 없어요.', '/files/nongsaro_img/37113123-91a7-422f-98bf-e370c8319f2c.jpg', true, now(), now()),
(103, 'Serissa foetida', '만천성', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '만천성은 꼭두서니과에 속하는 관목형 식물로, 아시아 동남부가 원산지예요. 이 식물은 5~6월에 흰색 또는 연한 붉은빛을 띤 자주색 꽃을 피우며, 잎은 마주나고 긴 타원형이에요. 번식은 주로 꺾꽂이와 포기나누기로 이루어지며, 관상용으로 많이 사용돼요.', '특별한 독성은 없지만, 민감한 사람은 주의가 필요해요.', '/files/nongsaro_img/6b085add-8142-42da-bd86-9cecd6d320ef.jpg', true, now(), now()),
(104, 'Trachelospermum asiaticum var. majus', '마삭줄', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '16~20℃', '마삭줄은 잎과 꽃이 크며 향기가 강한 덩굴성 식물이에요. 5월에서 6월 사이에 분홍색과 흰색의 꽃이 피며, 내건성은 강하지만 내한성은 약한 편이에요. 한국 남부지방이 원산지로, 실내에서 기르기에 적합해요.', '독성 정보가 없어요.', '/files/nongsaro_img/48d89697-4d6c-4581-8c22-ac1526d6de3f.JPG', true, now(), now()),
(105, 'Ficus benjamina', '벤자민고무나무', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '벤자민고무나무는 물밤나무과에 속하는 상록 교목으로, 실내 대형 화분으로 많이 사용돼요. 줄기가 유연하여 자유롭게 구부릴 수 있어 다양한 형태로 키울 수 있답니다. 꽃말은 ''변덕쟁이''로, 환경 변화에 민감하여 적응 기간이 필요해요.', '독성 정보가 없어요.', '/files/nongsaro_img/99040119-3dc0-41b7-8834-2a16e758d798.jpg', true, now(), now()),
(106, 'Ficus benjamina ''King''', '킹벤자민고무나무', 'NORMAL', 'LOW', 'NORMAL', true, '21~25℃', '킹벤자민고무나무는 뽕나무과에 속하는 식물로, 실내에서 잘 자라는 관엽식물이에요. 이 식물은 ''변덕쟁이''라는 꽃말을 가지고 있으며, 주로 삽목으로 번식해요. 잎은 녹색과 연두색의 점무늬가 특징적이에요.', '독성 정보가 없어요.', '/files/nongsaro_img/7a383ead-265a-4693-829b-a929ff93ad83.jpg', true, now(), now()),
(107, 'Ficus benghalensis', '벵갈고무나무', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '벵갈고무나무는 뽕나무과에 속하는 식물로, 주로 인도와 그 주변 지역에서 자생해요. 이 식물은 실타래처럼 늘어진 기근과 회백색의 줄기를 가지고 있어요. 실내에서 키우기 적합하며, 공기 정화 능력이 뛰어나요.', '벵갈고무나무의 일부는 섭취 시 독성이 있을 수 있어요. 특히 어린이와 애완동물의 접근을 피해야 해요.', '/files/nongsaro_img/108dd46d-779a-400e-a419-210910341795.jpg', true, now(), now()),
(108, 'Callistemon spp.', '병솔나무', 'NORMAL', 'HIGH', 'NORMAL', true, '21~25℃', '병솔나무는 호주와 파푸아뉴기니아가 원산지인 상록 소교목이에요. 붉은 솔 모양의 꽃은 가느다란 수술이 모여 방망이를 이루며, 5월에서 8월 사이에 피어요. 병솔나무는 병을 닦는 솔을 닮아 이름이 붙여졌으며, 원예종으로 많이 재배되고 있어요.', '병솔나무는 독성이 없어요.', '/files/nongsaro_img/b33eef72-ebae-449f-864c-cbd4911c6904.JPG', true, now(), now()),
(109, 'Nephrolepis exaltata ''Bostoniensis''', '보스톤고사리', 'FREQUENT', 'MEDIUM', 'EASY', true, '16~20℃', '보스톤고사리는 풍성하고 아름다운 잎 때문에 빅토리아 시대부터 실내에 도입되어 사랑받아온 식물이에요. 열대 원산종의 원예품종으로, 주로 공중걸이형으로 키우며 실내 장식용으로 인기가 많아요. 관리가 쉬워 초보자도 키우기 적합한 식물이에요.', '독성이 없어서 안전하게 키울 수 있어요.', '/files/nongsaro_img/7f27aca7-ef1a-4ba6-8a6e-4d8952955902.JPG', true, now(), now()),
(110, 'Pteris multifida', '프테리스', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '16~20℃', '프테리스는 고사리과에 속하는 식물로, 주로 한국, 일본, 중국 등지에서 자생해요. 잎은 우상복엽으로 1-3쌍이며, 증산효과가 뛰어나 실내 공기정화에 도움을 줘요. 관리가 비교적 쉬워 실내에서 키우기 적합한 식물이에요.', '프테리스는 독성이 거의 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/ef95d85c-6c4f-45c7-aa73-4e1ea93be9a0.JPG', true, now(), now()),
(111, 'Bougainvillea glabra', '부겐빌레아', 'FREQUENT', 'MEDIUM', 'EASY', true, '21~25℃', '부겐빌레아는 남아메리카 원산의 덩굴성 관목으로, 주로 브라질에서 자생해요. 이 식물은 높이 4~5m까지 자라며, 다양한 색상의 포가 꽃처럼 보이는 특징이 있어요. 한국에서는 주로 온실에서 재배되며, 관리가 비교적 쉬운 편이에요.', '부겐빌레아는 독성이 없지만, 섭취 시 소화 불량을 일으킬 수 있어요.', '/files/nongsaro_img/638f6e59-d361-4c8b-aaa0-8e92b5131723.jpg', true, now(), now()),
(112, 'Brunfelsia australis', '브룬펠시아', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '브룬펠시아는 실내에서 다양한 색상의 꽃을 피우며 은은한 향기를 발산하는 사랑스러운 나무예요. 처음에는 진보라색 꽃이 피고, 시간이 지나면서 연보라색과 흰색으로 변해요. 햇빛과 통풍이 필요하며, 물을 너무 자주 주면 잎이 떨어질 수 있어요.', '브룬펠시아는 독성이 없어요.', '/files/nongsaro_img/70f6c670-1caf-4518-b0ce-f5520df25a62.jpg', true, now(), now()),
(113, 'Vriesea', '브리세아', 'FREQUENT', 'MEDIUM', 'EASY', true, '21~25℃', '브리세아는 파인애플과에 속하는 상록다년초로, 주로 브라질 동남부에 자생해요. 약 250종이 있으며, 주로 착생종으로 대형의 지생종도 존재해요. 잎은 활모양으로 뻗고 가죽질이며, 꽃은 수상화서로 다양한 색상을 띠어요.', '브리세아는 독성이 없어요.', '/files/nongsaro_img/386ca878-673f-4372-a6af-751c7daad251.jpg', true, now(), now()),
(114, 'Chlorophytum bichetii', '스파이더 플랜트', 'NORMAL', 'LOW', 'NORMAL', true, '21~25℃', '스파이더 플랜트는 백합과에 속하는 식물로, 가봉, 인도 남부, 중국 남부가 원산지예요. 이 식물은 실내에서 잘 자라며, 공기 정화 능력이 뛰어나 많은 가정에서 사랑받고 있어요. 주로 잎을 관상용으로 키우며, 관리가 비교적 쉬운 편이에요.', '독성이 없어 반려동물과 함께 키우기 좋아요.', '/files/nongsaro_img/cc10a90f-26b8-4ba0-a2e9-7169b92b1554.JPG', true, now(), now()),
(115, 'Chlorophytum comosum var. vittatum', '접란', 'NORMAL', 'LOW', 'NORMAL', true, '21~25℃', '접란은 남아프리카가 원산지인 변종으로, 실내에서 잘 자라는 식물이에요. 이 식물은 공기 중의 포름알데히드를 제거하는 능력이 있어 공기 정화에 도움을 줍니다. 또한, 관리가 쉬워 초보자도 키우기 적합한 식물이에요.', '독성 정보는 알려져 있지 않아요.', '/files/nongsaro_img/34e1149d-399c-43da-bc01-19aaae300f85.JPG', true, now(), now()),
(116, 'Sansevieria trifasciata ''Golden Hahnii''', '산세베리아', 'NORMAL', 'LOW', 'EASY', true, '21~25℃', '산세베리아는 열대 서부 아프리카 원산의 변종으로, 주로 실내에서 관상용으로 재배돼요. 이 식물은 빛이 좋은 반그늘에서 잘 자라며, 여름철 강한 직사광선을 피하는 것이 좋아요. 겨울철에는 냉해를 주의해야 하며, 과습 시 뿌리가 썩을 수 있어요.', '산세베리아는 독성이 거의 없으나, 섭취 시 소화 불량을 유발할 수 있어요.', '/files/nongsaro_img/6a0489a6-760e-45c9-9853-c10dabbb6d71.jpg', true, now(), now()),
(117, 'Ardisia pusilla', '산호수', 'NORMAL', 'LOW', 'EASY', true, '16~20℃', '산호수는 자금우과에 속하는 덩굴식물로, 빨간 열매가 인상적이에요. 잎에 무늬가 있는 종류도 있지만, 무늬종은 열매가 잘 열리지 않는 특징이 있어요. 꽃, 열매, 잎 모두 관상가치가 높아 키우기 쉬운 관엽 식물이에요.', '특별한 독성 정보는 없어요.', '/files/nongsaro_img/2930767a-71b6-419f-99f9-a770843ba1cb.jpg', true, now(), now()),
(118, 'Ficus elastica', '고무나무', 'NORMAL', 'MEDIUM', 'EASY', false, '21~25℃', '고무나무는 두껍고 가죽 같은 잎을 가진 실내 관엽 식물이에요. 크림색이 잎 가장자리에 들어가 있어 고급스럽고 편안한 느낌을 줘요. 열대 아시아가 원산지이며, 실내에서 잘 자라는 식물이에요.', '고무나무의 수액은 피부에 자극을 줄 수 있어요. 섭취 시 소화 장애를 일으킬 수 있으니 주의하세요.', '/files/nongsaro_img/5ba5dd68-5543-4a86-a23f-f7606d5dc291.jpg', true, now(), now()),
(119, 'Humata tyermannii', '흰토끼발고사리', 'FREQUENT', 'LOW', 'EASY', true, '16~20℃', '흰토끼발고사리는 열대아시아와 말레이시아가 원산지인 고사리과 식물이에요. 흙 위로 올라온 발 모양의 뿌리에서 새순이 자라며, 습기를 잘 유지해야 건강하게 자랍니다. 너무 습하면 민달팽이와 곰팡이병이 생길 수 있고, 건조하면 깍지벌레가 발생할 수 있어요.', '독성 정보가 없으며, 안전하게 키울 수 있어요.', '/files/nongsaro_img/21153481-f04e-4380-b380-44a21216ea7a.gif', true, now(), now()),
(120, 'Calanthe discolor', '새우란', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '새우란은 난초과에 속하는 식물로, 주로 한국, 일본, 중국의 숲 속에서 자랍니다. 뿌리줄기가 새우를 닮아 이름이 붙었으며, 뿌리는 강장제로도 사용됩니다. 꽃이 아름답고 재배가 쉬운 편으로, 봄에 꽃이 피고 지면 영양제를 주어 이듬해에도 꽃을 잘 피울 수 있습니다.', '새우란은 독성이 없어요.', '/files/nongsaro_img/f9471ecb-db81-4d0d-8906-b8bab3485963.jpg', true, now(), now()),
(121, 'Acorus gramineus', '석창포', 'FREQUENT', 'MEDIUM', 'EASY', true, '16~20℃', '석창포는 중앙 동부아시아가 원산지인 다년생 초본으로, 주로 냇가에서 자랍니다. 근경은 옆으로 뻗으며 마디가 많고, 잎은 길이 30∼50cm로 대검 비슷한 선형입니다. 6-7월에 연한 황색 꽃이 피며, 근경은 진통, 진정 및 건위제로 사용됩니다.', '독성 정보가 없습니다.', '/files/nongsaro_img/15a22a54-959f-4a9a-9e04-604f5d721c99.jpg', true, now(), now()),
(122, 'Senecio radicans', '세네시오 라디칸스', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '세네시오 라디칸스는 남아프리카가 원산지인 다육질의 다년초로, 작은 녹색 바나나 모양의 잎이 특징이에요. 이 식물은 주로 행잉바스켓에 적합하며, 낮은 온도에서도 잘 견디지만 야간 온도는 13℃ 이상 유지해야 해요. 꽃은 흰색으로 향기가 있으며, 잎은 약용으로도 사용돼요.', '세네시오 라디칸스는 독성이 없지만, 섭취하지 않도록 주의해 주세요.', '/files/nongsaro_img/676570fd-21ff-49bd-8604-81d6039d8980.jpg', true, now(), now()),
(123, 'Chamaedorea seifrizii', '대나무야자', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '대나무야자는 멕시코와 중앙아메리카가 원산지인 야자과 식물로, 최대 2m까지 자랍니다. 줄기는 대나무와 비슷하며, 황갈색의 섬유질로 싸여 있습니다. 1989년 나사에서 발표한 우수 실내 정화 식물 중 하나로, 휘발성 화학물질 제거 능력이 뛰어납니다.', '검은색의 열매는 독성이 있어 섭취 시 주의가 필요합니다.', '/files/nongsaro_img/b6d6c01e-e443-42b0-b423-af2dd90dc125.jpg', true, now(), now()),
(124, 'Selaginella', '부처손', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '부처손은 주로 열대 우림지대에 자생하며, 줄기와 잎이 향나무 가지와 비슷한 모양을 가지고 있어요. 줄기는 연해 누워 자라고, 줄기에 뿌리가 내리며 자라는 특징이 있습니다. 이 식물은 주로 화훼 장식 재료로 사용되며, 작품의 밑 부분을 가리거나 수반화 아랫부분에 쓰여 작품의 아름다움을 더합니다.', '부처손은 독성이 없으므로 안전하게 키울 수 있어요.', '/files/nongsaro_img/1e71458c-e4eb-41aa-a08e-fb28272f59bc.gif', true, now(), now()),
(125, 'Cycas revoluta', '소철', 'NORMAL', 'MEDIUM', 'EASY', false, '21~25℃', '소철은 일본과 한국에서 유래된 식물로, 오랜 기간 동안 재배되어 왔어요. 이 식물은 손쉽게 관리할 수 있으며, 실내에서도 오래 살 수 있는 식물이에요. 성장 속도가 느리지만, 갑자기 새로운 잎을 여러 개 내는 경우도 있어요.', '소철의 씨앗과 잎은 독성이 있어 섭취 시 구토, 설사 등의 증상을 유발할 수 있어요.', '/files/nongsaro_img/56899a34-4fe8-4ba1-9799-3fb4c41fa818.jpg', true, now(), now()),
(126, 'Ficus elastica ''Sofia''', '소피아', 'NORMAL', 'LOW', 'NORMAL', false, '보통', '소피아 고무나무는 인도고무나무를 개량한 품종으로, 일반적인 멜라닌 고무나무보다 잎이 큽니다. 강한 직사광선을 피하되 실내의 밝은 곳에서 재배하며, 실내 습도를 40~70%로 유지해야 합니다. 깍지벌레와 응애와 같은 병충해를 조심해야 하며, 넓은 잎에 먼지가 쌓이면 젖은 헝겊으로 닦아주는 것이 좋습니다.', '고무나무의 수액은 피부에 자극을 줄 수 있으며, 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/42bbd6fc-5d6f-42fd-9837-7b54ef33b6f8.jpg', true, now(), now()),
(127, 'Soleirolia soleirolii', '천사의 눈물', 'INFREQUENT', 'MEDIUM', 'EASY', true, '16~20℃', '천사의 눈물은 내한성이 강한 상록 여러해살이풀로, 키는 약 5cm이며 줄기는 붉은색으로 30cm 정도 뻗어 나가요. 둥근 작은 잎이 촘촘히 달려있고 흰색 작은 꽃이 피며, 생명력이 강해 실내 적응력이 뛰어나요. 관수 시 화분의 흙이 말랐을 때 물을 주며, 잎이나 줄기에 물이 닿으면 곰팡이 병이 생길 수 있어 저면관수를 권장해요.', '독성이 없어요.', '/files/nongsaro_img/e998d6cd-3eb3-41f9-9cf3-b1c3b8540721.jpg', true, now(), now()),
(128, 'Peperomia sandersii', '수박페페', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '수박페페는 중앙 아메리카 원산의 후추과 식물로, 자일렌과 포름알데히드를 제거하는 능력이 뛰어난 공기정화식물이에요. 잎은 수박 무늬를 닮아 독특하며, 실내에서 키우기 적합해요. 겨울철에는 추위에 약하므로 온도 관리에 주의해야 해요.', '특별한 독성은 없으나, 모든 식물은 섭취를 피하는 것이 좋아요.', '/files/nongsaro_img/3b42ce48-20f6-4301-a8ce-269c7146ee84.jpg', true, now(), now()),
(129, 'Pilea cadierei', '알루미늄 식물', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '알루미늄 식물은 베트남과 멕시코가 원산지인 쐐기풀과의 식물이에요. 잎 표면에 은색 무늬가 있어 독특한 외관을 자랑하며, 실내에서 잘 자라요. 주로 관목형으로 성장하며, 특별한 관리가 필요해요.', '알루미늄 식물은 독성이 없어요.', '/files/nongsaro_img/123dd678-4b29-4320-b3cf-1af8594aeb59.jpg', true, now(), now()),
(130, 'Tillandsia usneoides', '스페니시 모스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '스페니시 모스는 파인애플과에 속하며, 미국 남동부와 아르헨티나 중부가 원산지예요. 이 식물은 뿌리가 없이 공중에서 습도와 영양분을 흡수하며 자라요. 주로 행잉으로 이용되며, 관리가 비교적 쉬운 편이에요.', '독성이 없으며, 사람과 동물에게 안전해요.', '/files/nongsaro_img/7560a13d-e272-49c3-8424-02aebb400fb7.jpg', true, now(), now()),
(131, 'Iberis sempervirens', '이베리스', 'NORMAL', 'HIGH', 'NORMAL', true, '21~25℃', '이베리스는 지중해 연안이 원산지인 다년생 식물로, 주로 흰색 꽃을 피워요. 주로 봄과 여름에 개화하며, 관목형으로 자라납니다. 관리가 비교적 쉬운 편이나, 경험이 있는 사람이 키우기에 적합해요.', '독성 정보는 없습니다.', '/files/nongsaro_img/272b4434-d1f7-4d24-a561-4022faad1829.jpg', true, now(), now()),
(132, 'Schefflera arboricola', '홍콩야자', 'NORMAL', 'LOW', 'EASY', true, '21~25℃', '홍콩야자는 실내 공기정화력이 우수한 식물로, 특히 담배 연기를 잘 흡수해요. 키가 큰 종류와 작은 왜성종이 있으며, 물꽂이 화분에서도 잘 자라요. 추위에 약하므로 겨울철 관리에 주의해야 해요.', '특별한 독성은 없지만, 섭취하지 않도록 주의하세요.', '/files/nongsaro_img/8cf98b09-be17-4085-b04f-e07c015aeead.jpg', true, now(), now()),
(133, 'Spathiphyllum ''Clevelandii''', '스파티필름', 'NORMAL', 'LOW', 'NORMAL', false, '21~25℃', '스파티필름은 천남성과에 속하는 식물로, 주로 실내에서 키우기 적합해요. 이 식물은 공기 정화 능력이 뛰어나며, 특히 포름알데히드와 벤젠 제거에 효과적이에요. 꽃은 흰색으로 봄과 여름에 피며, 관리가 비교적 쉬운 편이에요.', '스파티필름은 약간의 독성을 가지고 있어요. 섭취 시 구토나 설사를 유발할 수 있으니 주의해야 해요.', '/files/nongsaro_img/8b5a72ee-6a03-408d-bf32-d7878182348b.jpg', true, now(), now()),
(134, 'Cissus antarctica', '시서스 안타르티카', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '시서스 안타르티카는 포도과에 속하는 덩굴성 식물로, 주로 남미 북부와 서인도제도에서 자생해요. 잎은 난형으로 밝은 녹색이며 가장자리에 엉성한 톱니가 있어요. 오존에 민감하여 실내에서 오존경보장치 기능을 할 수 있어요.', '특별한 독성은 없지만, 섭취하지 않도록 주의하세요.', '/files/nongsaro_img/3ced122f-d340-47e7-8963-83143cb2128f.jpg', true, now(), now()),
(135, 'Aglaonema commutatum', '아글라오네마', 'NORMAL', 'LOW', 'NORMAL', true, '21~25℃', '아글라오네마는 영화 ‘레옹’의 주인공이 소중하게 여기던 화분식물로 잘 알려져 있어요. 은빛과 녹색이 잘 배합되어 고급스러운 느낌을 주며, 최근에는 화사한 빛깔의 품종 ‘오로라’도 유통되고 있어요. 추위에 약하므로 겨울철 실내온도를 잘 관리하며 수경재배로도 재배가 가능해요.', '아글라오네마는 독성이 거의 없지만, 섭취 시 소화 불량을 일으킬 수 있어요.', '/files/nongsaro_img/aebbd46e-b653-4983-8f0d-ed0dc60a51b5.jpg', true, now(), now()),
(136, 'Adenium obesum', '사막의 장미', 'INFREQUENT', 'HIGH', 'NORMAL', false, '21~25℃', '사막의 장미는 협죽도과에 속하는 다육식물로, 주로 남아프리카와 동아프리카가 원산지예요. 이 식물은 분홍색, 빨강색, 흰색의 화려한 꽃을 피우며, 건조한 환경에서도 잘 자라요. 관리가 비교적 쉬운 편이지만 경험이 있는 사람이 키우기에 적합해요.', '사막의 장미는 독성이 있어 섭취 시 구토와 설사를 유발할 수 있어요. 특히 어린이와 애완동물의 접근을 주의해야 해요.', '/files/nongsaro_img/add2a269-c225-48d4-a2f1-1eb55867d70c.jpg', true, now(), now()),
(137, 'Adiantum raddianum', '아디안텀', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '아디안텀은 고사리과에 속하는 식물로, 주로 브라질이 원산지예요. 밝은 녹색의 잎이 많이 달려 있어 매우 섬세한 느낌을 주며, 실내에서 키우기 적합해요. 실내의 습도를 측정할 수 있는 지표식물로도 사용되며, 잎이 부드럽고 원줄기는 윤기나는 검은색이에요.', '독성이 없어요.', '/files/nongsaro_img/e336e34f-3e76-4ae5-98ad-175a2dc32c44.jpg', true, now(), now()),
(138, 'Araucaria heterophylla', '아라우카리아', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '아라우카리아는 송곳모양의 부드러운 바늘이 있는 가지가 수평으로 자라는 우아한 상록성 나무예요. 공기정화능력이 우수하고 재배가 쉬워 실내식물로 기르기에 적합해요. 반음지나 반양지에서 잘 자라며 직접적으로 빛을 받으면 잎이 누렇게 타므로 직사광선은 피하는 게 좋습니다.', '특별한 독성은 없지만, 잎이 날카로워 주의가 필요합니다.', '/files/nongsaro_img/16954baa-c395-4639-9fd6-ccf3d7b0f27c.jpg', true, now(), now()),
(139, 'Dypsis lutescens', '아레카야자', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '아레카야자는 인도와 마다가스카르가 원산지인 야자과 식물이에요. NASA가 지정한 실내공기 정화 식물 중 하나로, 거실이나 사무실 등의 공기정화에 필수적인 식물이에요. 줄기가 황색을 나타내는 것은 병든 것이 아니라 원래 특성이에요.', '아레카야자는 독성이 없어 반려동물이 있는 가정에서도 안전해요.', '/files/nongsaro_img/de448358-edc9-4726-9a26-84ff13083ce6.gif', true, now(), now()),
(140, 'Hippeastrum hybridum', '아마릴리스', 'NORMAL', 'HIGH', 'EASY', true, '21~25℃', '아마릴리스는 남아메리카가 원산지인 백합과의 다년생 구근 식물이에요. 주로 봄과 여름에 분홍색, 빨강색, 흰색, 혼합색의 화려한 꽃을 피워요. 실내에서 키우기 쉬운 식물로, 높은 광도와 적당한 습도를 유지해주면 잘 자라요.', '아마릴리스는 독성이 거의 없어요.', '/files/nongsaro_img/3c14e0f9-6daf-4287-aba0-d087caabe204.jpg', true, now(), now()),
(141, 'Asparagus plumosus var. nanus', '아스파라거스 펄모서스', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '아스파라거스 펄모서스는 아프리카가 원산지인 덩굴성 식물이에요. 주로 실내에서 관상용으로 키우며, 잎이 부드럽고 가늘어 우아한 느낌을 줘요. 공기 정화 능력이 뛰어나 실내 공기질 개선에 도움을 줘요.', '독성은 없지만, 섭취하지 않도록 주의해 주세요.', '/files/nongsaro_img/14f43012-51b7-4dcb-bc9a-5bc74046b315.jpg', true, now(), now()),
(142, 'Asplenium nidus', '고사리', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '고사리는 연녹색의 광택 있는 잎이 시원한 관엽식물로, 창모양의 반짝이는 잎이 로제트 형태로 자라 둥지 모양을 형성해요. 주로 중국남부, 대만, 인도에서 자생하며, 실내에서 키우기 적합한 식물이에요. 관리에는 경험이 필요하며, 습도 유지가 중요해요.', '독성은 없지만, 어린아이나 반려동물이 섭취하지 않도록 주의해요.', '/files/nongsaro_img/8edf1f36-85a4-4fdf-9dd6-500d624548dd.jpg', true, now(), now()),
(143, 'Viburnum odoratissimum var. awabuki', '아와부키', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '아와부키는 인동과에 속하는 관목형 식물로 일본, 타이완, 중국에서 자생해요. 이 식물은 봄에 흰색 꽃을 피우며, 여름과 가을에는 빨간색 열매를 맺어요. 관리가 쉬워 초보자도 키우기 적합하며, 실내에서도 잘 자라요.', '독성 정보가 없어요.', '/files/nongsaro_img/2e602b21-0404-4e4b-9ec2-0ef37e36b2e1.jpg', true, now(), now()),
(144, 'Aphelandra squarrosa', '아펠란드라', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '아펠란드라는 중앙 아메리카와 브라질이 원산지인 식물로, 주로 실내에서 재배됩니다. 이 식물은 노란색 꽃과 줄무늬가 있는 잎이 특징이며, 공기 정화 능력이 뛰어납니다. 적절한 관리가 필요하며, 특히 물과 습도 관리에 주의해야 합니다.', '특별한 독성은 없으나, 어린아이와 애완동물이 섭취하지 않도록 주의하세요.', '/files/nongsaro_img/806bc6e0-6ce7-4d2d-b397-e655c6035319.jpg', true, now(), now()),
(145, 'Saintpaulia spp.', '아프리칸 바이올렛', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '아프리칸 바이올렛은 다년생 식물로, 다육질의 타원형 잎에 털이 있으며 다양한 색상의 꽃을 피워요. 이 식물은 아프리카가 원산지이며, 일반적으로 실내에서 잘 자라요. 꽃말은 ''작은 사랑''으로, 꽃이 작고 귀여운 특성에서 유래했어요.', '독성이 없어요.', '/files/nongsaro_img/63c6e27e-2104-43ee-bebf-5c049ec0cf80.gif', true, now(), now()),
(146, 'Anthurium andraeanum', '안스리움', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '안스리움은 중앙 아메리카가 원산지인 천남성과의 식물이에요. 이 식물은 일산화탄소와 암모니아 가스를 제거하는 능력이 뛰어나 주방이나 화장실에 적합해요. 광택이 있는 포엽이 아름다워 실내에서 관상용으로 많이 기르며, 다양한 색상의 꽃을 피워요.', '안스리움은 옥살산칼슘을 함유하고 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/d4a37164-cd28-4445-9342-7d3452c13375.jpg', true, now(), now()),
(147, 'Alocasia amazonica', '알로카시아 아마조니카', 'FREQUENT', 'MEDIUM', 'HARD', false, '21~25℃', '알로카시아 아마조니카는 동남아시아가 원산지인 천남성과 식물이에요. 이 식물은 독특한 잎 모양과 색상으로 인테리어 식물로 인기가 많아요. 관리가 까다로워 전문가 수준의 관리가 필요해요.', '알로카시아 아마조니카는 옥살산칼슘을 함유하고 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/7fc69f65-65bf-403f-a82f-38f1e936c662.jpg', true, now(), now()),
(148, 'Alocasia cucullata', '알로카시아', 'FREQUENT', 'MEDIUM', 'EASY', false, '16~20℃', '알로카시아는 천남성과에 속하는 식물로, 주로 열대와 아열대 지역에서 자라요. 이 식물은 잎이 크고 독특한 모양을 가지고 있어 실내 장식용으로 인기가 많아요. 관리가 쉬워 초보자도 키우기 적합해요.', '알로카시아는 옥살산칼슘을 함유하고 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/ff4a1fa1-2e7c-404d-b100-32da9de4791f.jpg', true, now(), now()),
(149, 'Tradescantia zebrina', '제브리나', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '제브리나는 멕시코가 원산지인 덩굴성 식물로, 실내에서 잘 자라며 초보자에게 적합해요. 잎은 녹색, 연두색, 은색, 회색, 빨강, 분홍, 자주색의 다양한 색상을 띠고 있어 관상용으로 인기가 많아요. 주로 삽목으로 번식하며, 봄과 여름에 분홍색과 흰색의 꽃을 피워요.', '제브리나는 독성이 없어서 반려동물과 함께 키우기 좋아요.', '/files/nongsaro_img/43801fb4-9f48-40ea-a58a-29d423678937.jpg', true, now(), now()),
(150, 'Acalypha reptans', '여우꼬리풀', 'INFREQUENT', 'HIGH', 'NORMAL', true, '21~25℃', '여우꼬리풀은 인도와 동남아시아가 원산지인 대극과의 식물이에요. 주로 실내에서 관상용으로 키우며, 붉은색과 분홍색의 독특한 꽃을 피워요. 관리가 비교적 쉬운 편이나, 높은 광도와 적절한 습도를 유지해주는 것이 중요해요.', '여우꼬리풀은 독성이 없어서 반려동물과 함께 키우기 안전해요.', '/files/nongsaro_img/3a0aa7dc-9c24-49cb-a6ce-2295e209cd1c.jpg', true, now(), now()),
(151, 'Aspidistra elatior', '아스피디스트라', 'NORMAL', 'LOW', 'EASY', true, '16~20℃', '아스피디스트라는 백합과에 속하는 식물로 일본과 중국 남부가 원산지예요. 이 식물은 낮은 광도에서도 잘 자라며, 실내에서 키우기 적합해요. 특히 공기 중의 포름알데히드와 벤젠을 제거하는 능력이 있어 공기 정화에 도움을 줘요.', '독성 정보가 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/b72c5b5b-31bc-4871-a13e-8d713882fe08.jpg', true, now(), now()),
(152, 'Oxalis triangularis', '자주 괭이밥', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '자주 괭이밥은 아열대 지방이 원산지인 식물로, 보라색, 분홍색, 흰색의 꽃을 피워요. 잎은 녹색, 연두색, 빨강, 분홍, 자주색 등 다양한 색상을 띠며, 잎과 꽃을 감상하기 좋은 식물이에요. 관리 난이도는 경험자 수준이며, 실내에서 키우기 적합해요.', '특별한 독성은 없어요.', '/files/nongsaro_img/257e89c9-4955-4243-9e5f-f4b1044c7d17.jpg', true, now(), now()),
(153, 'Ophiopogon japonicus', '왜란', 'NORMAL', 'MEDIUM', 'EASY', true, '10~15℃', '왜란은 일본 원산의 백합과 식물로, 주로 지피식물로 사용돼요. 녹색과 연두색의 잎을 가지며, 관리가 쉬워 초보자에게 적합해요. 주로 실내에서 키우며 공기 정화 능력이 있어요.', '왜란은 독성이 없어요.', '/files/nongsaro_img/d06aa101-fb3f-43af-a538-0a01642aab3c.jpg', true, now(), now()),
(154, 'Rhapis multifida', '라피스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '라피스는 야자과에 속하는 식물로 중국 북부가 원산지예요. 주로 실내에서 관상용으로 키우며, 중간에서 높은 광도를 필요로 해요. 성장 속도는 느리며, 관리 난이도는 경험자 수준이에요.', '독성 정보가 없어요.', '/files/nongsaro_img/de674921-9b58-48ed-9140-c74f8e62450e.jpg', true, now(), now()),
(155, 'Ficus umbellata', '피쿠스 움벨라타', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '피쿠스 움벨라타는 뽕나무과에 속하는 식물로 열대 아프리카가 원산지예요. 이 식물은 주로 실내에서 관상용으로 기르며, 잎이 크고 무늬가 없는 것이 특징이에요. 관리가 비교적 쉬운 편이지만 적절한 온도와 습도를 유지해주는 것이 중요해요.', '피쿠스 움벨라타는 독성이 없어요.', '/files/nongsaro_img/89ef8461-c63e-472b-b5a9-a2263636cfa7.jpg', true, now(), now()),
(156, 'Yucca', '유카', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '유카는 북부 아메리카의 사막과 평원에서 기원한 식물로, 뻣뻣하고 가죽 같은 잎과 크림색의 꽃이 특징이에요. 실내 식물로 키우기 적합하며, 겨울철에는 서리가 없는 장소에서 관리해야 해요. 이 식물은 뛰어난 정원 우수성 상을 받은 바 있어요.', '유카는 일반적으로 독성이 없어요.', '/files/nongsaro_img/6a126216-c884-4fcf-81c0-f8ec649da20f.jpg', true, now(), now()),
(157, 'Euonymus japonicus ''Albomarginata''', '사철나무', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '사철나무는 노박덩굴과에 속하는 상록 관목으로, 한국과 일본이 원산지예요. 이 품종은 잎 가장자리에 흰색 무늬가 있어 장식용으로 인기가 많아요. 실내에서도 잘 자라며, 공기 정화 능력이 있어 실내 식물로 적합해요.', '사철나무는 일반적으로 독성이 없으나, 섭취 시 주의가 필요해요.', '/files/nongsaro_img/edd25544-b386-49ce-a33a-f459c0a2b9a1.jpg', true, now(), now()),
(158, 'Ixora chinensis', '산호수', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '산호수는 동남아시아가 원산지인 꼭두서니과의 상록저목이에요. 꽃이 피어 있는 시간이 길고 짙은 녹색의 잎이 매혹적으로 빛나요. 꽃은 피지만 열매는 맺지 않는 것이 특징이에요.', '독성이 없어서 안전하게 키울 수 있어요.', '/files/nongsaro_img/b219b2c7-b98f-4d75-a1b2-8a9a8676bf62.jpg', true, now(), now()),
(159, 'Ficus microcarpa', '인도고무나무', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '인도고무나무는 동남아시아가 원산지인 뽕나무과 식물이에요. 이 식물은 실내에서 관상용으로 많이 키우며, 공기 정화 능력이 뛰어나요. 관리가 비교적 쉬운 편이지만, 적절한 광도와 습도를 유지해야 건강하게 자랄 수 있어요.', '인도고무나무의 수액은 피부에 자극을 줄 수 있으며, 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/b1204da8-3ff9-430f-9496-23614f2d3efa.jpg', true, now(), now()),
(160, 'Bletilla striata', '자란', 'INFREQUENT', 'MEDIUM', 'EASY', true, '16~20℃', '자란은 아시아 원산의 난초과 식물로, 주로 봄에 분홍색과 흰색 혼합의 꽃을 피워요. 관리가 쉬워 초보자도 키우기 좋으며, 실내에서도 잘 자라요. 주로 발코니 내측이나 창측에 두면 적합해요.', '자란은 독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/f202fd3a-7082-4a9a-abaf-98218c7512e4.jpg', true, now(), now()),
(161, 'Rhoeo discolor', '부자란', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '부자란은 자주빛을 띠는 닭의장풀과 식물로, 단독화분에 심어도 아름답습니다. 멕시코가 원산지이며, 통풍이 좋은 곳에서 햇빛을 받아야 건강하게 자랍니다. 이 식물은 경험자가 관리하기 적합하며, 실내에서도 잘 자랍니다.', '부자란은 독성이 없어 안전하게 키울 수 있습니다.', '/files/nongsaro_img/0b0e6001-d51a-4356-8e12-3abca7791e44.jpg', true, now(), now()),
(162, 'Trachelospermum ''Atsuba Chirimen''', '아시아틱 자스민', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '아시아틱 자스민은 협죽도과에 속하는 덩굴성 식물로, 한국 남부 지역에서 주로 발견돼요. 이 식물은 잎의 색상이 녹색, 연두색, 금색, 노란색으로 다양하며, 점무늬가 있어 관상용으로 인기가 많아요. 관리가 비교적 쉬운 편이며, 실내에서 잘 자라므로 인테리어 식물로 적합해요.', '독성 정보가 없으며, 안전한 식물이에요.', '/files/nongsaro_img/f272b3bf-d931-46f9-af01-10127d0a88e8.jpg', true, now(), now()),
(163, 'Cyperus alternifolius', '파피루스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '파피루스는 마다가스카르가 원산지인 사초과 식물로, 주로 수경형으로 자랍니다. 이 식물은 물가나 수조에서 잘 자라며, 빠르게 성장하는 특징이 있습니다. 관리 난이도는 경험자 수준으로, 적절한 물과 비료 관리가 필요합니다.', '특별한 독성은 없습니다.', '/files/nongsaro_img/bab295ae-a387-4c36-bde7-36af1996442a.jpg', true, now(), now()),
(164, 'Rhapis humilis', '라피스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~20℃', '라피스는 주로 한국, 일본, 중국 남부에서 자생하는 야자과 식물이에요. 이 식물은 주로 실내에서 관상용으로 키우며, 관리가 비교적 쉬운 편이에요. 공기 정화 능력이 있어 실내 공기질 개선에 도움을 줄 수 있어요.', '독성 정보가 알려져 있지 않아요.', '/files/nongsaro_img/755240e5-66b8-4d6c-9981-fd2677720685.jpg', true, now(), now()),
(165, 'Podocarpus nagi', '나한송', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '나한송은 나한송과에 속하는 상록수로, 주로 북아메리카 남부에서 자생해요. 이 식물은 직립형으로 자라며, 잎은 녹색과 연두색을 띠고 있어요. 관리가 쉬워 초보자도 키우기 적합한 식물이에요.', '독성이 없어서 안전하게 키울 수 있어요.', '/files/nongsaro_img/9c48b301-208a-41f8-bd1c-aba40ff89f2b.jpg', true, now(), now()),
(166, 'Cyrtomium caryotideum var. koreanum', '물고사리', 'FREQUENT', 'LOW', 'EASY', true, '16~20℃', '물고사리는 한국 특산종으로 제주도와 여수 등지에서 자생해요. 이 식물은 고비과에 속하며, 실내에서도 잘 자라는 특성이 있어요. 관리가 쉬워 초보자도 키우기 적합한 식물이에요.', '독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/4ca6460b-0a70-4dc1-8c4a-2e402d4b5acb.jpg', true, now(), now()),
(167, 'Calathea insignis', '칼라데아 인시그니스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '칼라데아 인시그니스는 중앙 아메리카 원산의 마란타과 식물이에요. 잎의 무늬가 선명하여 실내 장식용으로 인기가 많아요. 어두운 곳에 오래 있으면 잎 끝이 아래로 처지거나 싹 끝이 시드는 증상이 나타날 수 있어요.', '독성 정보가 알려져 있지 않아요.', '/files/nongsaro_img/0ea5ea74-94c1-4bcb-a70c-3457d44a6e7a.jpg', true, now(), now()),
(168, 'Calathea crocata', '칼라데아 크로카타', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '칼라데아 크로카타는 중앙 아메리카가 원산지인 마란타과의 식물이에요. 주로 실내에서 관상용으로 키우며, 오렌지색과 노란색의 아름다운 꽃을 피워요. 공기 중의 습도를 좋아하며, 비교적 관리가 쉬운 편이에요.', '칼라데아 크로카타는 독성이 없는 식물로 알려져 있어요.', '/files/nongsaro_img/1cb7f198-d83b-47c3-a1fe-d563055ccac2.jpg', true, now(), now()),
(169, 'Caladium bicolor', '칼라디움', 'NORMAL', 'MEDIUM', 'HARD', false, '21~25℃', '칼라디움은 중앙 아메리카가 원산지인 천남성과 식물로, 화려한 잎 무늬가 특징이에요. 이 식물은 주로 실내 장식용으로 인기가 많으며, 관리가 까다로워 전문가 수준의 관리가 필요해요. 잎의 색상은 녹색, 연두색, 빨강, 분홍, 자주색 등 다양한 색상이 혼합되어 있어요.', '칼라디움은 칼슘 옥살레이트를 함유하고 있어 섭취 시 구토, 설사 등의 증상을 유발할 수 있어요.', '/files/nongsaro_img/5ec1cc8a-6d2d-4299-9a3a-7cf1c70909dd.jpg', true, now(), now()),
(170, 'Coffea arabica', '커피나무', 'NORMAL', 'HIGH', 'NORMAL', true, '21~25℃', '커피나무는 꼭두서니과에 속하는 식물로, 열대 아시아 및 아프리카가 원산지예요. 이 식물은 주로 실내에서 관상용으로 기르며, 흰색 꽃과 빨간색 열매를 맺어요. 관리 난이도가 다소 있어 경험자에게 적합한 식물이에요.', '독성 정보는 없어요.', '/files/nongsaro_img/de2dea14-9b3a-48af-bd54-2ad5dc281eb5.jpg', true, now(), now()),
(171, 'Howea forsteriana', '켄티아야자', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '켄티아야자는 오스트레일리아 원산의 야자과 식물로, 실내에서 잘 자라며 관리가 비교적 쉬운 편이에요. 이 식물은 공기 정화 능력이 뛰어나며, 포름알데히드와 벤젠 등의 유해 물질을 제거하는 데 효과적이에요. 또한, 직립형으로 자라며 최대 2미터까지 성장할 수 있어요.', '켄티아야자는 독성이 없어 반려동물과 함께 키우기 좋아요.', '/files/nongsaro_img/4c255199-bd6b-439c-8107-6c85f83c7bb7.jpg', true, now(), now()),
(172, 'Cordyline terminalis', '홍콩야자', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '홍콩야자는 동남아시아와 오스트레일리아, 폴리네시아가 원산지인 식물이에요. 잎 가장자리에 무늬가 있으며, 녹색과 연두색의 잎을 가지고 있어요. 직립형으로 자라며, 실내에서 키우기 적합한 식물이에요.', '특별한 독성은 없어요.', '/files/nongsaro_img/d8aa9a6d-88fb-4436-b02c-87d83676fb69.jpg', true, now(), now()),
(173, 'Codiaeum variegatum', '크로톤', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '크로톤은 열대성 상록 관목으로 다양한 잎 모양과 색상을 가진다. 빛에 대한 적응성이 강하여 어두운 곳에서도 잘 견디며, 잎의 무늬가 독특하다. 온도 변화에 민감하여 저온에서는 잎이 쉽게 떨어진다.', '크로톤의 잎과 줄기는 독성이 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/978d4202-5c8c-4b92-99f3-45be54564c54.jpg', true, now(), now()),
(174, 'Codiaeum variegatum var. pictum', '코디아에움', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '코디아에움은 동남아시아가 원산지인 상록 관목으로, 주로 실내 장식용으로 재배돼요. 이 식물은 다양한 색상의 잎을 가지며, 따뜻하고 습한 환경에서 잘 자라요. 관리가 다소 까다로울 수 있으며, 밝은 빛과 일정한 온도를 유지하는 것이 중요해요.', '코디아에움의 잎과 줄기에는 독성이 있어 섭취 시 구토나 설사를 유발할 수 있어요.', '/files/nongsaro_img/d5fdf0dd-6c46-405e-bca7-5ad11abc2f88.jpg', true, now(), now()),
(175, 'Cryptanthus spp.', '크립탄서스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '크립탄서스는 파인애플과에 속하는 식물로, 주로 브라질에서 자생해요. 이 식물은 지피식물로 건조에 강하며 기르기 쉬운 특징이 있어요. 로제트형의 잎을 가지며, 다양한 색상의 줄무늬가 특징이에요.', '크립탄서스는 독성이 없어 반려동물이 있는 가정에서도 안전해요.', '/files/nongsaro_img/18361550-360a-4615-ae4f-8643e833ac0e.jpg', true, now(), now()),
(176, 'Clematis florida', '클레마티스', 'FREQUENT', 'HIGH', 'NORMAL', false, '21~25℃', '클레마티스는 미나리아재비과에 속하는 덩굴성 식물로, 주로 중국에서 유래했어요. 꽃이 피는 시기에는 물을 충분히 주고, 올라갈 지지대가 필요해요. 실내에서는 발코니 창가에 두어 높은 광도를 유지하는 것이 좋아요.', '클레마티스의 모든 부분은 독성이 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/12a6e0ad-4f91-406e-a948-65262a0e21f5.jpg', true, now(), now()),
(177, 'Tradescantia sillamontana', '털달개비', 'INFREQUENT', 'HIGH', 'NORMAL', true, '21~25℃', '털달개비는 중앙아메리카가 원산지인 닭의장풀과 식물이에요. 잎과 줄기에 흰 털이 덮여 있어 독특한 외관을 가지고 있으며, 보라색과 분홍색의 꽃을 피워요. 건조한 환경에서도 잘 자라며, 실내에서도 키우기 적합해요.', '털달개비는 독성이 없어서 반려동물에게 안전해요.', '/files/nongsaro_img/6db0a441-78eb-445e-b11a-10ac0bc0ccf7.jpg', true, now(), now()),
(178, 'Farfugium japonicum [털머위]', '털머위', 'NORMAL', 'LOW', 'NORMAL', true, '16~20℃', '털머위는 국화과에 속하는 다년생 식물로, 주로 한국 남해안과 일본, 대만, 중국에서 자생해요. 이 식물은 주로 잎과 꽃을 감상하기 위해 실내에서 키우며, 노란색 꽃이 봄과 여름에 피어요. 특유의 무늬 없는 녹색 잎과 연두색 잎이 특징이며, 실내에서 공기 정화에도 도움을 줄 수 있어요.', '털머위는 독성이 거의 없으나, 섭취하지 않도록 주의하세요.', '/files/nongsaro_img/ea039390-d33a-4820-a350-d7639bdbcd2a.jpg', true, now(), now()),
(179, 'Chamaedorea elegans', '테이블야자', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '테이블야자는 멕시코와 과테말라가 원산지인 작은 야자과 식물이에요. 공기 중 수분을 방출하며 벤젠과 포름알데히드 등의 화학물질을 제거하는 데 효과적이에요. 책상 위에 올려놓고 키우기 좋아 탁상야자라고도 불려요.', '독성이 없으며, 반려동물에게도 안전해요.', '/files/nongsaro_img/4681196e-fdc4-423c-840b-483a3c7b8ffd.jpg', true, now(), now()),
(180, 'Tolmiea menziesii', '피기백플랜트', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '피기백플랜트는 북아메리카 서해안이 원산지인 범의귀과의 식물이에요. 주로 실내에서 관상용으로 기르며, 잎이 독특한 모양을 가지고 있어요. 관리가 비교적 쉬운 편이지만, 적절한 온도와 습도를 유지하는 것이 중요해요.', '피기백플랜트는 독성이 없어요.', '/files/nongsaro_img/bed896e6-8bb8-4fdb-bd80-8c84275730fa.jpg', true, now(), now()),
(181, 'Tillandsia cyanea', '틸란드시아 시아네아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '틸란드시아 시아네아는 파인애플과에 속하는 식물로, 주로 페루와 에콰도르가 원산지예요. 이 식물은 분홍색 화포에서 남보라색 꽃이 차례로 피며, 같은 포에서 여러 장의 꽃잎을 올려요. 열대식물로 추위에 약하므로 따뜻한 환경에서 잘 자라요.', '독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/98010495-cd05-450b-85b2-d91292817a8e.jpg', true, now(), now()),
(182, 'Paphiopedilum hybrids', '파피오페딜럼', 'INFREQUENT', 'MEDIUM', 'HARD', true, '21~25℃', '파피오페딜럼은 난초과에 속하는 식물로, 주로 열대 및 아열대 아시아에서 자생해요. 이 식물은 다양한 색상의 꽃을 피우며, 꽃 모양이 독특하여 ''Lady''s slipper''라는 별명을 가지고 있어요. 관리가 까다로워 전문가 수준의 관리가 필요해요.', '독성 정보가 없어요.', '/files/nongsaro_img/e48e5ab7-80d3-4093-84e6-d695eac00b9a.jpg', true, now(), now()),
(183, 'Phalaenopsis spp.', '호접란', 'NORMAL', 'MEDIUM', 'HARD', true, '21~25℃', '호접란은 동남아시아가 원산지인 난초과 식물로, 주로 실내에서 관상용으로 키워요. 꽃은 분홍색, 오렌지색, 노랑색, 흰색 등 다양한 색상을 가지며, 봄, 여름, 겨울에 개화해요. 관리가 까다로워 전문가 수준의 관리가 필요해요.', '호접란은 독성이 없어요.', '/files/nongsaro_img/cbed2e53-4e58-4bdd-9ddd-c235681af96c.jpg', true, now(), now()),
(184, 'Fatsia japonica', '팔손이', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '팔손이는 두릅나무과에 속하는 상록 관목으로, 한국 남해안과 일본이 원산지예요. 손가락처럼 7~11열로 깊게 갈라진 큰 잎이 특징이며, 잎은 짙은 녹색으로 광택이 있어요. 주로 실내 관엽식물로 키우며 관리가 쉬워 초보자에게 적합해요.', '독성이 없어 반려동물과 함께 키우기에 안전해요.', '/files/nongsaro_img/108a2447-e17b-4775-ab1e-f1243a3408c7.jpg', true, now(), now()),
(185, 'Ficus panda', '피쿠스 판다', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '피쿠스 판다는 뽕나무과에 속하는 식물로, 주로 실내에서 관상용으로 키워요. 이 식물은 관리가 비교적 쉬운 편이며, 적당한 습도와 온도를 유지하면 잘 자라요. 잎은 녹색과 연두색으로, 무늬가 없는 것이 특징이에요.', '피쿠스 판다는 독성이 거의 없지만, 섭취하지 않도록 주의해 주세요.', '/files/nongsaro_img/04e00c1d-914d-448d-9b61-28b487762552.jpg', true, now(), now()),
(186, 'Fatshedera lizei', '아이비나무', 'NORMAL', 'MEDIUM', 'EASY', true, '16~20℃', '아이비나무는 두릅나무과에 속하는 식물로, 칠레가 원산지예요. 이 식물은 실내에서 잘 자라며, 관리가 쉬워 초보자에게 적합해요. 잎은 녹색과 연두색으로, 무늬가 없는 것이 특징이에요.', '독성 정보가 없어요.', '/files/nongsaro_img/d49ae6e5-f151-49dc-a3e7-9d2a479cb1b8.jpg', true, now(), now()),
(187, 'Peperomia obtusifolia', '페페로미아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '페페로미아는 중앙 아메리카가 원산지인 다육질의 잎을 가진 식물이에요. 잎은 두껍고 광택이 있으며 다양한 색상을 띠고 있어 실내 장식용으로 인기가 많아요. 관리가 비교적 쉬운 편이지만 경험이 있는 사람이 키우기에 적합해요.', '독성이 없어 반려동물과 함께 키우기 좋아요.', '/files/nongsaro_img/b13671cf-5728-4949-8a50-2986b04fcec7.jpg', true, now(), now()),
(188, 'Peperomia clusiifolia', '페페로미아 클루시폴리아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '페페로미아 클루시폴리아는 중앙 아메리카가 원산지인 후추과 식물이에요. 이 식물은 주로 잎을 감상하기 위해 실내에서 기르며, 관리가 비교적 쉬운 편이에요. 잎 가장자리에 붉은색 무늬가 있어 독특한 매력을 가지고 있어요.', '페페로미아 클루시폴리아는 독성이 없어 반려동물에게 안전해요.', '/files/nongsaro_img/32657b39-f1b2-454a-961f-70dc354304dd.jpg', true, now(), now()),
(189, 'Peperomia puteolata [페페로미아 푸테올라타]', '페페로미아 푸테올라타', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '페페로미아 푸테올라타는 중앙 아메리카가 원산지인 다육형 식물이에요. 잎은 녹색과 연두색의 줄무늬가 특징이며, 실내에서 쉽게 기를 수 있어요. 관리가 비교적 쉬운 편이지만, 경험이 있는 사람이 기르기에 적합해요.', '페페로미아 푸테올라타는 독성이 없어 안전해요.', '/files/nongsaro_img/5ca74ebd-875f-4512-b596-08b54425e2c4.jpg', true, now(), now()),
(190, 'Polyscias balfouriana ''Marginata''', '폴리시아스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '폴리시아스는 두릅나무과에 속하는 식물로, 풍성하고 섬세한 잎과 부드럽게 늘어뜨려진 가지가 매력적이에요. 주로 실내에서 관상용으로 인기가 많으며, 관리가 비교적 쉬운 편이에요. 뉴칼레도니아가 원산지로, 따뜻한 온도에서 잘 자랍니다.', '특별한 독성 성분은 없지만, 섭취는 피하는 것이 좋아요.', '/files/nongsaro_img/5958acc6-7d6c-4190-b4e2-35214274e90b.jpg', true, now(), now()),
(191, 'Ficus pumila', '무화과나무', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '무화과나무는 덩굴성 관엽식물로 실내화단 지피용으로 많이 사용돼요. 한국, 일본, 중국 남부가 원산지이며, 실내에서 키우기 적합한 식물이에요. 이 식물은 21~25℃의 온도에서 잘 자라며, 겨울철에는 10℃ 이상의 온도를 유지해야 해요.', '무화과나무는 독성이 없어요.', '/files/nongsaro_img/b9ad4145-c1fa-4dd8-a0d1-9e4177725cd5.jpg', true, now(), now()),
(192, 'Pteris cretica', '크레타 고사리', 'FREQUENT', 'LOW', 'EASY', true, '21~25℃', '크레타 고사리는 고사리과에 속하는 식물로, 주로 실내 정원에서 색상을 더하는 데 사용해요. 잎은 우상복엽으로 중앙에 흰 무늬가 있어 관상 가치가 높아요. 한국, 일본, 중국, 동남아시아가 원산지이며 실내에서 기르기 쉬운 식물이에요.', '독성이 없어 반려동물과 함께 키우기 좋아요.', '/files/nongsaro_img/a413902d-8b98-46c6-b7e0-b38c3b6dfb05.jpg', true, now(), now()),
(193, 'Pyracantha coccinea', '피라칸타', 'FREQUENT', 'HIGH', 'NORMAL', false, '16~20℃', '피라칸타는 장미과에 속하는 관목으로, 주로 울타리나 장식용으로 사용돼요. 봄에는 흰 꽃을 피우고 여름과 가을에는 빨강, 오렌지, 노랑의 열매를 맺어요. 관리가 비교적 쉬운 편이며, 높은 광도와 적절한 습도를 유지하면 잘 자라요.', '피라칸타의 열매는 섭취 시 복통이나 구토를 유발할 수 있어요.', '/files/nongsaro_img/e69523a4-3f5e-4913-85e3-a3e3af4c08fd.jpg', true, now(), now()),
(194, 'Fittonia verschaffeltii ''Pink Star''', '핑크스타 피토니아', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '핑크스타 피토니아는 남아메리카 페루가 원산지인 식물로, 고온다습한 환경에서 잘 자라요. 잎에 독특한 줄무늬가 있어 관엽식물로 인기가 많아요. 생장이 느리고 공중습도 유지가 중요해요.', '독성 정보가 없어요.', '/files/nongsaro_img/c3c09958-202f-403b-b7d7-c5dcb6a25bd1.jpg', true, now(), now()),
(195, 'Fittonia verschaffeltii ''White Star''', '핏토니아 화이트 스타', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '핏토니아 화이트 스타는 남아메리카 페루가 원산지인 쥐꼬리망초과 식물이에요. 고온다습한 환경에서 잘 자라며, 강한 햇빛에 노출되면 잎이 탈 수 있어 주의해야 해요. 실내에서 밝은 그늘이나 반그늘에서 키우기 적합해요.', '특별한 독성은 없으나, 섭취 시 주의가 필요해요.', '/files/nongsaro_img/84437716-61d8-474d-b0c9-d238b3338a14.jpg', true, now(), now()),
(196, 'Chlorophytum comosum [스파이더 플랜트]', '스파이더 플랜트', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '스파이더 플랜트는 아프리카 원산의 백합과 식물로, 실내에서 잘 자라는 식물이에요. 이 식물은 공기정화 능력이 뛰어나며, 초보자도 쉽게 관리할 수 있어요. 잎은 녹색과 흰색의 줄무늬가 있어 시각적으로도 매력적이에요.', '스파이더 플랜트는 독성이 없어 반려동물에게도 안전해요.', '/files/nongsaro_img/8d1e5bf4-6a5d-4c7a-84a0-6ca86a7bd3b0.jpg', true, now(), now()),
(197, 'Pilea glauca', '타라', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '타라는 덩굴성 관엽식물로, 실내화단 지피용이나 공중걸이, 실내화분으로 적합해요. 남아프리카가 원산지이며, 관리가 쉬워 초보자에게 적합해요. 잎은 녹색, 연두색, 은색, 회색으로 다양하며, 무늬는 없어요.', '타라는 독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/1ef0517f-322b-4451-8654-6289c009bbd1.jpg', true, now(), now()),
(198, 'Philodendron ''Sunlight''', '필로덴드론 선라이트', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '필로덴드론 선라이트는 잎의 광택이 있고 두꺼워서 환경에 적응하는 힘이 큰 식물이에요. 이 식물은 일반적으로 실내에서 잘 자라며, 중간에서 높은 광도를 필요로 해요. 관리가 비교적 쉬운 편이지만 경험자에게 적합해요.', '특별한 독성은 없지만, 잎을 섭취하지 않도록 주의해 주세요.', '/files/nongsaro_img/85a1b14c-dee2-4052-96e7-c4b054a3ddf3.jpg', true, now(), now()),
(199, 'Philodendron ''Xanadu''', '제나두', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '제나두는 천남성과에 속하는 식물로, 잎이 떨어진 흔적이 오래된 나무와 같은 모양을 하고 있어요. 이 식물은 실내에서 중간에서 높은 광도를 필요로 하며, 관리가 비교적 쉬운 편이에요. 공기 중의 오염 물질을 제거하는 능력이 있어 실내 공기 정화에 도움을 줄 수 있어요.', '제나두는 독성이 있어 섭취 시 구토나 설사를 유발할 수 있어요. 반려동물과 어린이의 손이 닿지 않는 곳에 두세요.', '/files/nongsaro_img/11c7940b-5097-4ae4-aa67-011cb88f4792.jpg', true, now(), now()),
(200, 'Philodendron goeldii', '필로덴드론 고엘디', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '필로덴드론 고엘디는 천남성과에 속하는 식물로, 주로 실내에서 관상용으로 기르는 식물이에요. 이 식물은 중간에서 높은 광도를 필요로 하며, 관리 난이도가 경험자 수준이에요. 잎은 녹색과 연두색으로, 실내 공기 정화에 도움을 줄 수 있어요.', '독성이 거의 없지만, 섭취는 피하는 것이 좋아요.', '/files/nongsaro_img/5a6ab655-f538-4ecb-9471-07369a47d4a6.jpg', true, now(), now()),
(201, 'Philodendron ''Lemon Lime''', '필로덴드론 레몬라임', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '필로덴드론 레몬라임은 천남성과에 속하는 덩굴성 식물로, 실내에서 잘 자라며 공기정화 능력이 뛰어나요. 잎은 녹색과 연두색을 띠며, 밝은 실내 환경에서 가장 잘 자랍니다. 관리가 비교적 쉬운 편이지만, 적절한 온도와 습도를 유지하는 것이 중요해요.', '필로덴드론은 칼슘 옥살레이트를 함유하고 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/038d7c78-fe6b-4f72-a777-361a386ad095.jpg', true, now(), now()),
(202, 'Philodendron oxycardium', '스위트 하트 바인', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '스위트 하트 바인은 천남성과에 속하는 덩굴성 식물로, 주로 실내에서 관상용으로 재배돼요. 이 식물은 서인도제도와 중앙 아메리카가 원산지이며, 잎은 녹색과 연두색으로 무늬가 없어요. 관리가 비교적 쉬운 편이지만, 적절한 온도와 습도를 유지해야 건강하게 자랄 수 있어요.', '스위트 하트 바인은 독성이 있어 섭취 시 구토, 설사 등의 증상을 유발할 수 있어요.', '/files/nongsaro_img/e11d1ebc-3f81-4fe0-8a50-8b00709179f7.jpg', true, now(), now()),
(203, 'Philodendron ''Congo''', '필로덴드론 콩고', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '필로덴드론 콩고는 천남성과에 속하는 관엽식물로, 실내에서 잘 자라요. 이 식물은 관리가 비교적 쉬운 편이며, 공기 정화 능력이 있어 실내 공기질 개선에 도움을 줘요. 잎은 녹색과 연두색으로 빛나며, 실내 인테리어에 적합해요.', '필로덴드론 콩고는 섭취 시 구토나 설사를 유발할 수 있어요. 어린이와 반려동물의 접근을 피하세요.', '/files/nongsaro_img/d53fb3d5-5ea1-448e-9636-24bf694de45c.jpg', true, now(), now()),
(204, 'Haemaria discolor var. dawsoniana', '보석난초', 'FREQUENT', 'LOW', 'HARD', true, '21~25℃', '보석난초는 인도네시아와 버마가 원산지인 난초과 식물이에요. 이 식물은 낮은 광도에서도 잘 자라며, 주로 실내에서 관상용으로 키워요. 꽃은 봄과 여름에 피며 분홍색과 흰색을 띄어요.', '특별한 독성은 없어요.', '/files/nongsaro_img/997bc0d4-6780-4bd6-875a-14591c3c9ba9.jpg', true, now(), now()),
(205, 'Dracaena fragrans', '드라세나 프래그란스', 'NORMAL', 'MEDIUM', 'EASY', false, '21~25℃', '드라세나 프래그란스는 백합과에 속하는 식물로, 아프리카가 원산지예요. 이 식물은 실내에서 잘 자라며, 공기 정화 능력이 뛰어나 거실에 두기 좋아요. 관리가 쉬워 초보자도 키우기 적합한 식물이에요.', '드라세나 프래그란스는 반려동물에게 독성이 있을 수 있어요. 섭취 시 구토나 설사를 유발할 수 있으니 주의하세요.', '/files/nongsaro_img/6b2c063c-071e-4789-b730-1622cc03c2e7.jpg', true, now(), now()),
(206, 'Hemionitis arifolia', '하트고사리', 'FREQUENT', 'MEDIUM', 'NORMAL', true, '21~25℃', '하트고사리는 하트 모양의 잎이 매력적인 관엽식물이에요. 서인도와 멕시코가 원산지로, 실내에서 기르기 적합해요. 습한 환경을 좋아하지만 과습은 피해야 해요.', '독성은 없으나, 어린이나 반려동물이 먹지 않도록 주의하세요.', '/files/nongsaro_img/2dd1e5eb-1d78-4a2c-ad73-a9d58d2016e6.jpg', true, now(), now()),
(207, 'Heteropanax fragrans', '헤테로파낙스 프라그란스', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '헤테로파낙스 프라그란스는 두릅나무과에 속하는 식물로, 주로 중국, 인도, 인도네시아 등지에서 자생해요. 이 식물은 실내에서 키우기 적합하며, 관리 난이도는 경험자 수준이에요. 공기 정화 능력이 있어 실내 공기 질 개선에 도움을 줄 수 있어요.', '독성 정보는 없어요.', '/files/nongsaro_img/1d8fac2f-563e-409b-9d18-042dba0390aa.jpg', true, now(), now()),
(208, 'Nerium oleander', '협죽도', 'NORMAL', 'HIGH', 'EASY', false, '21~25℃', '협죽도는 동남아시아, 서남아시아, 북아프리카가 원산지인 관목형 식물이에요. 여름철에 분홍색과 흰색의 아름다운 꽃을 피우며, 강한 독성을 가지고 있어 주의가 필요해요. 관리가 쉬운 편으로 초보자도 키우기 적합하지만, 독성으로 인해 어린이와 반려동물의 접근을 피해야 해요.', '협죽도는 모든 부위에 강한 독성을 가지고 있어요. 섭취 시 구토, 설사, 심장 문제를 일으킬 수 있으니 주의하세요.', '/files/nongsaro_img/fbd32157-483c-49f6-b211-e1d90c3478f4.jpg', true, now(), now()),
(209, 'Epipremnum aureum ''Lime''', '스킨답서스 라임', 'NORMAL', 'MEDIUM', 'NORMAL', false, '21~25℃', '스킨답서스 라임은 동남아시아가 원산지인 덩굴성 식물이에요. 잎은 녹색과 연두색, 금색, 노란색의 다양한 색상을 띠며 실내 장식용으로 인기가 많아요. 관리가 비교적 쉬워 경험자에게 적합한 식물이에요.', '스킨답서스는 옥살산 칼슘을 함유하고 있어 섭취 시 구토와 설사를 유발할 수 있어요.', '/files/nongsaro_img/24b817f3-0c84-4a94-bc3b-30a5404a9e04.jpg', true, now(), now()),
(210, 'Hoya carnosa [호야]', '호야', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '호야는 박주가리과에 속하는 덩굴성 다육식물로, 일본 남부와 중국, 오스트레일리아, 대만이 원산지예요. 이 식물은 주로 실내에서 관상용으로 기르며, 잎과 꽃을 감상할 수 있어요. 꽃은 봄과 여름에 분홍색과 흰색으로 피며, 향기가 거의 없어요.', '호야는 독성이 없어서 반려동물과 함께 키우기 좋아요.', '/files/nongsaro_img/00820d1b-fa93-45b1-a173-25734309131a.jpg', true, now(), now()),
(211, 'Leptospermum scoparium', '호주매화', 'INFREQUENT', 'HIGH', 'NORMAL', true, '21~25℃', '호주매화는 도금양과에 속하는 관목형 식물로, 주로 호주와 뉴질랜드에서 자생해요. 이 식물은 분홍색, 빨강색, 흰색의 아름다운 꽃을 봄과 여름에 피우며, 약한 향기를 가지고 있어요. 관리 난이도는 경험자 수준으로, 적절한 온도와 습도 관리가 필요해요.', '독성 정보가 없어요.', '/files/nongsaro_img/7eb3ba44-8248-4682-8543-9d70dfe68013.jpg', true, now(), now()),
(212, 'Peperomia angulata', '페페로미아 앵귤라', 'NORMAL', 'MEDIUM', 'NORMAL', true, '21~25℃', '페페로미아 앵귤라는 중앙 아메리카가 원산지인 후추과 식물이에요. 잎은 녹색과 연두색의 줄무늬가 특징이며, 실내에서 잘 자라요. 관리가 비교적 쉬운 편이지만 경험이 있는 사람에게 적합해요.', '독성이 거의 없어서 반려동물에게 안전해요.', '/files/nongsaro_img/2a130bc9-d8a7-4ce0-a8f6-f52f01623ed2.jpg', true, now(), now()),
(213, 'Dracaena sanderiana [행운목]', '행운목', 'NORMAL', 'MEDIUM', 'NORMAL', false, '16~20℃', '행운목은 백합과에 속하는 식물로, 주로 실내에서 관상용으로 키워요. 카메룬이 원산지이며, 공기 중의 포름알데히드, 벤젠 등을 제거하는 데 효과적이에요. 관리가 비교적 쉬워 초보자도 키우기 좋지만, 적절한 광도와 습도를 유지해야 건강하게 자라요.', '행운목은 독성이 있어 반려동물이나 어린이가 섭취하지 않도록 주의해야 해요. 섭취 시 구토, 설사 등의 증상이 나타날 수 있어요.', '/files/nongsaro_img/5515a3b5-5012-4205-a494-ccda10ece00a.jpg', true, now(), now()),
(214, 'Ternstroemia japonica', '차나무과', 'NORMAL', 'HIGH', 'EASY', true, '16~20℃', 'Ternstroemia japonica는 광택이 나는 잎과 붉은 열매가 아름다운 식물이에요. 한국 원산지로, 관목형으로 자라며 주로 실내에서 기르기 적합해요. 관리가 쉬운 편이라 초보자도 키우기 좋아요.', '독성 정보가 없으며, 안전하게 키울 수 있어요.', '/files/nongsaro_img/5fec42a2-eb9c-4023-b202-325b5bd64341.jpg', true, now(), now()),
(215, 'Zephyranthes candida', '흰꽃나도사프란', 'INFREQUENT', 'HIGH', 'EASY', true, '21~25℃', '흰꽃나도사프란은 수선화과에 속하는 다년생 초본식물로, 주로 남아메리카가 원산지예요. 이 식물은 흰색 꽃을 피우며, 여름과 가을에 개화합니다. 관리가 쉬워 초보자도 키우기 적합한 식물이에요.', '흰꽃나도사프란은 독성이 없어 안전하게 키울 수 있어요.', '/files/nongsaro_img/26204c70-b7df-414d-bfd3-1e07dc8748af.jpg', true, now(), now()),
(216, 'Tradescantia albiflora ''Albovittata''', '인치플랜트', 'NORMAL', 'MEDIUM', 'EASY', true, '21~25℃', '인치플랜트는 덩굴성 관엽식물로, 빛이 잘 드는 곳에서 잘 자라요. 브라질 원산지로, 잎에 줄무늬가 있어 장식용으로 인기가 많아요. 빛이 부족하면 잎의 무늬가 사라질 수 있으니 주의해야 해요.', '독성은 거의 없으나, 섭취 시 주의가 필요해요.', '/files/nongsaro_img/9b68014f-83ce-453f-90c0-e078d894aa1b.jpg', true, now(), now()),
(217, 'Hypoestes phyllostachya', '폴카닷 식물', 'FREQUENT', 'MEDIUM', 'EASY', true, '21~25℃', '폴카닷 식물은 마다가스카르가 원산지인 관엽식물로, 다양한 색상의 점무늬 잎이 특징이에요. 실내에서 쉽게 키울 수 있으며, 주로 장식용으로 사용돼요. 적당한 습도와 온도를 유지하면 잘 자라요.', '독성은 없어요.', '/files/nongsaro_img/382ce558-b988-4ceb-9975-802fbc2b5f9d.jpg', true, now(), now()),
(218, 'Fittonia verschaffeltii', '피토니아', 'NORMAL', 'LOW', 'EASY', true, '15~25°C', '피토니아는 남아메리카 원산의 쥐꼬리망초과 식물로, 주로 실내에서 관상용으로 기릅니다. 이 식물은 반음지에서 잘 자라며, 공기 중 음이온 발생량이 높아 실내 공기 정화에 도움을 줍니다. 또한, 다양한 색상의 잎과 도드라진 잎맥이 특징이며, 테라리움이나 행잉바스켓에 심어 장식하기 좋습니다.', '피토니아는 독성이 없으며, 안전하게 실내에서 기를 수 있습니다.', 'https://www.nihhs.go.kr/img/air/air_tech_img166.jpg', true, now(), now()),
(219, 'Tillandsia cyanea [틸란드시아]', '틸란드시아', 'NORMAL', 'LOW', 'NORMAL', true, '생육적온 7~15°C', '틸란드시아는 파인애플과에 속하는 착생식물로, 주로 열대 아메리카에서 자생해요. 이 식물은 공기 중에서 양분을 흡수하며, 화려한 꽃을 감상하기 위해 많이 재배돼요. 자일렌과 포름알데히드 제거에 탁월한 공기정화 능력을 가지고 있어요.', '특별한 독성은 없어요.', 'https://www.nihhs.go.kr/img/air/air_tech_img147.jpg', true, now(), now()),
(220, 'Plectranthus tomentosa', '장미허브', 'INFREQUENT', 'LOW', 'EASY', true, '15~25°C', '장미허브는 지중해 연안이 원산지인 꿀풀과의 여러해살이풀로, 장미 모양의 잎에서 사과향과 레몬향이 나는 것이 특징이에요. 두꺼운 잎과 줄기를 가지고 있어 물을 많이 필요로 하지 않으며, 일반 허브식물보다 약간 건조하게 기르는 것이 좋아요. 실내에서 기를 때에는 직사광선을 피하고 햇빛이 잘 드는 창가에 두는 것이 좋으며, 음이온 발생량이 매우 우수하여 공부방에 두면 집중력을 도와준답니다.', '장미허브는 독성이 없어서 안전하게 기를 수 있어요.', 'https://www.nihhs.go.kr/img/air/air_tech_img131.jpg', true, now(), now()),
(221, 'Mentha suaveolens', '애플민트', 'NORMAL', 'HIGH', 'EASY', true, '15~20°C', '애플민트는 유럽 원산의 여러해살이풀로, 사과와 박하를 섞어 놓은 듯한 향기를 가지고 있어요. 주로 요리의 향신료로 사용되며, 피로 회복에 좋은 약용으로도 쓰여요. 내한성이 있어 노지에서도 월동이 가능하지만, 실내에서는 햇빛이 많이 드는 곳에서 잘 자랍니다.', '애플민트는 독성이 없어 안전하게 키울 수 있어요.', NULL, true, now(), now()),
(222, 'Pteris multifida Poir', '봉의꼬리', 'NORMAL', 'LOW', 'EASY', true, '생육적온 15°C', '봉의꼬리는 한국을 포함한 동아시아에 자생하는 상록다년초로, 주로 반그늘에서 잘 자랍니다. 이 식물은 포름알데히드 제거 능력이 뛰어나며, 실내 습도 조절에도 효과적이에요. 봉의꼬리는 가늘고 긴 잎을 가지며, 관상용으로 인기가 많습니다.', '봉의꼬리는 독성이 없어 안전하게 키울 수 있습니다.', 'https://www.nihhs.go.kr/img/air/air_tech_img88.jpg', true, now(), now()),
(223, 'Ficus benghalensis [벵갈고무나무]', '벵갈고무나무', 'NORMAL', 'MEDIUM', 'NORMAL', false, '생육적온 25~30°C', '벵갈고무나무는 인도와 동남아시아가 원산지인 뽕나무과의 상록 목본 식물이에요. 주로 실내 조경식물로 이용되며, 잎의 독특한 무늬와 공기정화 능력으로 인기가 많아요. 줄기에 상처를 내면 하얀 수액이 나오는데, 이는 생고무의 원료로 사용되기도 해요.', '벵갈고무나무의 수액은 피부에 닿으면 자극을 줄 수 있어요. 어린이와 애완동물이 섭취하지 않도록 주의해야 해요.', NULL, true, now(), now()),
(224, 'Ardisia crenata [백량금]', '백량금', 'NORMAL', 'LOW', 'EASY', false, '7~15°C', '백량금은 자금우과에 속하는 상록성 관목으로, 붉은 열매와 광택 있는 잎이 특징이에요. 주로 한국, 일본, 중국의 섬과 숲 그늘에서 자생하며, 실내에서는 빛이 부족한 곳에서도 잘 자랍니다. 포름알데히드 제거 능력이 뛰어나 공기정화 식물로도 인기가 많아요.', '백량금의 열매는 독성이 있어 섭취 시 구토나 설사를 유발할 수 있어요.', 'https://www.nihhs.go.kr/img/air/air_tech_img61.jpg', true, now(), now()),
(225, 'Zamia furfuracea', '멕시코소철', 'NORMAL', 'MEDIUM', 'NORMAL', true, '15~25°C', '멕시코소철은 멕시코 동부 연안이 원산지인 소철과의 열대산 상록교목이에요. 잎 표면에 갈색 잔털이 뒤덮여 있어 수분 증발을 방지하고 병원균으로부터 보호해요. 햇빛을 좋아하며, 물이 부족하면 잎이 누렇게 변할 수 있어요.', '멕시코소철은 독성이 없어요.', 'https://www.nihhs.go.kr/img/air/air_tech_img55.jpg', true, now(), now()),
(226, 'Rosmarinus officinalis', '로즈마리', 'NORMAL', 'HIGH', 'NORMAL', false, '온도', '로즈마리는 지중해 연안이 원산지인 허브로, ''바다의 이슬''이라는 뜻을 가지고 있어요. 이 식물은 강한 햇빛 아래에서 잘 자라며, 엷은 자줏빛 꽃이 4~5월에 피어요. 로즈마리는 요리와 화장품에 널리 사용되며, 특히 기억력 증강에 도움이 되는 카르노신산을 함유하고 있어요.', '로즈마리는 고혈압이나 간질 증상이 있는 사람에게 자극적일 수 있어요. 임신 중에는 사용을 피하는 것이 좋아요.', 'https://www.nihhs.go.kr/img/air/air_tech_img39.jpg', true, now(), now()),
(227, 'Aloysia triphylla', '레몬버베나', 'NORMAL', 'LOW', 'EASY', true, '생육적온 15~20°C', '레몬버베나는 아르헨티나와 칠레가 원산지인 비내한성 낙엽성 관목이에요. 이 식물은 강한 레몬 향을 가지고 있으며, 톨루엔과 같은 공기 중 오염 물질을 효과적으로 제거해요. 주로 허브티, 향수, 비누 등에 사용되며, 실내에서는 햇빛이 잘 드는 곳에 두는 것이 좋아요.', '레몬버베나는 독성이 없으며, 안전하게 사용할 수 있어요.', NULL, true, now(), now()),
(228, 'Lavandula species', '라벤더', 'NORMAL', 'HIGH', 'NORMAL', true, '15~25°C', '라벤더는 지중해 연안이 원산지인 허브 식물로, 약 25~30여 종이 있습니다. 꽃과 잎, 줄기를 덮고 있는 미세한 털 사이에서 향기가 나는 기름샘이 있어 향수와 화장품의 원료로 사용됩니다. 또한, 두통이나 신경안정 치료에 사용되며, 포름알데히드 제거에 탁월한 공기정화 효과가 있습니다.', '라벤더는 일반적으로 독성이 없으나, 일부 사람에게는 알레르기 반응을 일으킬 수 있습니다.', NULL, true, now(), now()),
(229, 'Dendrobium Sw.', '던파레', 'NORMAL', 'MEDIUM', 'NORMAL', true, '생육적온 18~20°C', '던파레는 난초과에 속하는 식물로, 열대아시아와 오스트레일리아가 원산지예요. 이 식물은 주로 실내에서 기르며, 포름알데히드 제거에 효과적이에요. 덴드로비움 팔레높시스 계열로 꽃이 화려하고 오래가는 특징이 있어요.', '독성 정보는 없어요.', 'https://www.nihhs.go.kr/img/air/air_tech_img009.jpg', true, now(), now()),
(230, 'Ardisia pusilla [산호수]', '산호수', 'NORMAL', 'LOW', 'NORMAL', true, '20~25℃', '산호수는 제주도에서 자생하는 식물로, 빨간 열매와 광택 나는 잎이 특징이에요. 음이온을 발생시켜 집중력 향상과 실내 습도 조절에 도움이 돼요. 덩굴성으로 자라며, 잎에 광택이 있어 고급스러운 느낌을 줘요.', '독성 정보가 없어요.', NULL, true, now(), now()),
(231, 'Rhododendron fauriei', '만병초', 'NORMAL', 'LOW', 'NORMAL', false, '10~20℃', '만병초는 우리나라의 희귀 및 멸종위기 식물로, 만가지 병을 고친다는 의미에서 이름이 붙여졌어요. 주로 고산지대에서 자라며, 햇볕이 많이 들지 않는 습한 환경을 선호해요. 톨루엔 제거 능력이 뛰어나 공기정화 식물로도 알려져 있어요.', '만병초는 잎과 꽃에 그레이아노톡신이라는 독성 물질이 있어 섭취 시 구토, 설사 등의 증상을 유발할 수 있어요.', NULL, true, now(), now()),
(232, 'Ficus benjamina [벤자민고무나무]', '벤자민고무나무', 'NORMAL', 'MEDIUM', 'NORMAL', false, '낮 16~24℃, 밤 13~20℃', '벤자민고무나무는 뽕나무과에 속하는 식물로, 환경 변화에 민감하여 이동을 싫어하지만 적응하면 무성하게 자라요. 실내에 들여오면 적응하는 동안 잎이 떨어질 수 있으며, 겨울에는 오래된 잎이 자연적으로 떨어져요. 아황산가스와 자동차 배기가스를 제거하는 데 효과적이에요.', '벤자민고무나무의 수액은 피부에 닿으면 자극을 줄 수 있으며, 섭취 시 위장 장애를 일으킬 수 있어요.', NULL, true, now(), now()),
(233, 'Nandina domestica [남천]', '남천', 'NORMAL', 'HIGH', 'NORMAL', true, '15~25℃', '남천은 매자나무과에 속하는 상록성 식물로, 한국, 일본, 중국, 인도에 자생합니다. 가을부터 겨울까지 빨갛게 물드는 열매와 잎이 특징이며, 새집증후군의 원인물질인 포름알데히드를 효과적으로 제거하는 공기정화 능력을 가지고 있습니다. 또한, 톨루엔 제거 능력도 우수하여 실내 공기질 개선에 도움을 줍니다.', '남천은 일반적으로 독성이 없는 식물로 알려져 있어요.', NULL, true, now(), now()),
(234, 'Aglaonema crispum ''Silver Queen''', '아글라오네마 실버퀸', 'FREQUENT', 'LOW', 'EASY', false, '상온', '아글라오네마 실버퀸은 천남성과에 속하는 실내 관엽식물로, 동남아시아가 원산지예요. 이 식물은 빛이 부족한 환경에서도 잘 자라며, 공기 중의 독성 물질을 제거하는 능력이 뛰어나요. 그러나 저온에는 약해 13℃ 이하에서는 생육이 어려워요.', '아글라오네마 실버퀸은 피부와 점막을 자극하는 물질을 함유하고 있으며, 열매는 독성이 있어 섭취 시 주의가 필요해요.', NULL, true, now(), now()),
(235, 'Davallia mariesii', '넉줄고사리', 'NORMAL', 'LOW', 'EASY', true, '20~25℃', '넉줄고사리는 우리나라에서 자생하는 다년생 양치식물로, 바위나 나무에 착생하여 자랍니다. 꽃은 피지 않지만 잎의 번식이 빨라 사철 내내 싱그러운 녹색을 감상할 수 있습니다. 특히 포름알데히드 제거능력이 뛰어나 공기정화 식물로 인기가 많습니다.', '독성 정보가 없습니다.', NULL, true, now(), now()),
(236, 'Fatsia japonica [팔손이]', '팔손이', 'NORMAL', 'MEDIUM', 'EASY', true, '시원한 온도', '팔손이는 두릅나무과에 속하는 상록성 식물로, 우리나라 남해안 지방에서 노지 월동이 가능합니다. 11월경에 흰 꽃이 피고 열매를 맺으며, 잎은 보통 7갈래 또는 9갈래로 갈라져 있습니다. 공기 중의 톨루엔과 포름알데히드를 제거하는 능력이 뛰어나 실내 공기 정화에 효과적입니다.', '팔손이는 독성이 없어 안전하게 키울 수 있습니다.', NULL, true, now(), now()),
(237, 'Phalaenopsis spp. [팔레높시스]', '팔레높시스', 'NORMAL', 'LOW', 'EASY', true, '21~27℃ 낮, 16~18℃ 밤', '팔레높시스는 난과에 속하는 식물로, 주로 인도 동부와 동남아시아, 인도네시아, 필리핀, 호주 북부, 뉴기니가 원산지예요. 이 식물은 실내에서 이국적인 분위기를 자아내며, 일년 내내 꽃을 피울 수 있어요. 특히 밤에 공기 중의 이산화탄소를 흡수하여 정화하는 능력이 뛰어나 침실에 두기 적합해요.', '팔레높시스는 독성이 없어 안전하게 실내에서 키울 수 있어요.', NULL, true, now(), now()),
(238, 'Anthurium andraeanum [안스리움]', '안스리움', 'NORMAL', 'MEDIUM', 'NORMAL', false, '18~24℃', '안스리움은 천남성과에 속하는 열대 식물로, 주로 관상용으로 재배됩니다. 이 식물은 다양한 색상의 불염포를 가지고 있으며, 실내에서 기르기에는 까다로운 편입니다. 공기 중의 일산화탄소와 암모니아 가스를 제거하는 능력이 뛰어나 주방이나 화장실에 적합합니다.', '안스리움은 칼슘 옥살레이트를 함유하고 있어 섭취 시 구토와 설사를 유발할 수 있습니다.', NULL, true, now(), now()),
(239, 'Rosmarinus officinalis [로즈마리]', '로즈마리', 'NORMAL', 'HIGH', 'NORMAL', false, '15℃ 이상', '로즈마리는 지중해 연안이 원산지인 다년생 식물로, 강한 햇빛 아래에서 자라며 독특한 향기를 발합니다. 이 식물은 톨루엔과 포름알데히드 같은 휘발성 유기 화합물을 제거하는 데 탁월한 공기정화 능력을 가지고 있습니다. 또한, 로즈마리는 카르노신산 성분 덕분에 기억력을 증진시키는 효과가 있어 공부방에 두면 좋습니다.', '로즈마리는 고혈압이나 간질 증상이 있는 사람에게 자극적일 수 있으며, 임신 중에는 사용을 피해야 해요.', NULL, true, now(), now()),
(240, 'Dieffenbachia picta', '디펜바키아', 'NORMAL', 'LOW', 'EASY', false, '16~29℃', '디펜바키아는 천남성과에 속하는 관엽식물로, 주로 콜롬비아, 베네수엘라, 에콰도르가 원산지예요. 이 식물은 포름알데히드 제거 능력이 뛰어나 새집증후군 완화에 효과적이에요. 또한, 상대습도와 일산화탄소 제거 능력도 높아 실내 공기정화에 유용해요.', '디펜바키아의 수액에는 옥살산칼슘이 들어 있어, 섭취 시 혀와 성대가 마비될 수 있어요. 어린이와 애완동물이 접근하지 않도록 주의해야 해요.', NULL, true, now(), now()),
(241, 'Tulipa gesneriana', '튜립', 'FREQUENT', 'MEDIUM', 'NORMAL', false, '13~21℃', '튜립은 겨울부터 봄까지 꽃을 감상할 수 있는 인기 있는 분화식물이에요. 알뿌리 식물로, 꽃색은 빨강, 노랑 등 다양한 색상이 있어요. 네덜란드가 튜립의 주요 생산지이며, 우리나라에서도 주로 네덜란드로부터 수입하여 재배하고 있어요.', '튜립의 알뿌리에는 독성이 있어 섭취 시 구토나 설사를 유발할 수 있어요. 어린이와 애완동물이 접근하지 않도록 주의하세요.', NULL, true, now(), now()),
(242, 'Philodendron erubescens', '필로덴드론 에루베스센스', 'NORMAL', 'LOW', 'EASY', false, '16~21℃', '필로덴드론 에루베스센스는 남아메리카 원산의 덩굴성 식물로, 실내에서 기르기 적합해요. 어린잎은 선명한 적자색을 띠며, 관리가 용이한 편이에요. 주로 습하고 따뜻한 환경에서 잘 자라며, 지주를 세워주는 것이 좋아요.', '필로덴드론 에루베스센스는 섭취 시 구토와 설사를 유발할 수 있는 독성을 가지고 있어요.', NULL, true, now(), now()),
(243, 'Gerbera jamesonii', '거베라', 'NORMAL', 'HIGH', 'NORMAL', true, '16~18℃', '거베라는 국화과에 속하는 다년생 식물로, 주로 남아프리카가 원산지입니다. 다양한 색상의 꽃을 피우며, 절화로도 인기가 높습니다. 실내에서도 잘 자라며 공기 중 유독성 가스를 제거하는 데 효과적입니다.', '거베라는 독성이 없는 안전한 식물입니다.', NULL, true, now(), now()),
(244, 'Dendranthema grandiflorum', '분화 국화', 'NORMAL', 'MEDIUM', 'NORMAL', true, '낮 16~18℃, 밤 7~10℃', '분화 국화는 실내 장식용으로 많이 사용되는 식물로, 다양한 꽃색과 선명한 색상으로 사무실이나 가게에서 인기를 끌어요. 주로 가을철에 많이 볼 수 있지만, 재배 기술의 발달로 인해 일년 내내 감상할 수 있어요. 실내 공기 중 포름알데히드, 벤젠, 암모니아를 제거하는 데 효과적이에요.', '분화 국화는 독성이 없어요.', NULL, true, now(), now()),
(245, 'Nephrolepis obliterata', '네프롤레피스 오블리테라타', 'NORMAL', 'LOW', 'EASY', true, '18~24℃', '네프롤레피스 오블리테라타는 고사리과에 속하는 식물로, 보스톤 고사리보다 건조에 강해 실내 환경에 적합해요. 이 식물은 포름알데히드와 알코올을 제거하는 공기 정화 능력이 뛰어나고, 증산율이 높아 천연 가습기로도 활용할 수 있어요. 잎은 윤기 있는 녹색으로 우아한 아치를 그리며 늘어져 아름다움을 더해요.', '독성은 없지만, 잎을 섭취하지 않도록 주의해야 해요.', NULL, true, now(), now()),
(246, 'Epipremnum aureum [에피프레넘]', '에피프레넘', 'NORMAL', 'LOW', 'EASY', false, '낮 ; 18~24℃, 겨울에도 10℃이상 유지', '에피프레넘은 천남성과에 속하는 덩굴성 식물로, 녹색 하트모양의 잎에 황색 또는 크림색 무늬가 특징이에요. 이 식물은 관리가 쉬워 초보자에게 적합하며, 병해충에 강한 저항성을 가지고 있어요. 실내에서 잘 자라며, 삽목을 통해 쉽게 번식할 수 있어요.', '에피프레넘의 즙액은 피부 및 점막을 자극할 수 있으니 주의해야 해요.', NULL, true, now(), now()),
(247, 'Nephrolepis exaltata ''Bostoniensis'' [보스톤 고사리]', '보스톤 고사리', 'NORMAL', 'MEDIUM', 'NORMAL', true, '낮 18~24℃, 밤 10~18℃', '보스톤 고사리는 고사리과에 속하는 식물로, 실내에서 인기가 높은 관엽식물이에요. 이 식물은 주로 잎을 감상하기 위해 기르며, 공기 중의 포름알데히드를 제거하는 데 효과적이에요. 건조한 환경을 싫어하므로 자주 분무해 주는 것이 중요해요.', '보스톤 고사리는 독성이 없으며, 안전하게 실내에서 기를 수 있어요.', NULL, true, now(), now()),
(248, 'Ficus macleilandii ''Alii''', '알리 고무나무', 'NORMAL', 'MEDIUM', 'EASY', false, '16~24℃', '알리 고무나무는 최근 인기가 상승하고 있는 고무나무의 새로운 종류로, 짙은 녹색의 가늘고 긴 잎이 특징이에요. 태국에서 유래된 이 식물은 1980년대에 미국 시장에 도입되었으며, 벤자민 고무나무보다 키우기 쉬워 실내 조경용으로 인기가 높아요. 병충해에 강하고 공기정화 능력이 뛰어나 가정과 사무실에 적합한 식물이에요.', '알리 고무나무의 수액은 피부에 자극을 줄 수 있으며, 섭취 시 소화기 장애를 일으킬 수 있어요.', NULL, true, now(), now()),
(249, 'Phoenix roebelenii', '피닉스야자', 'NORMAL', 'MEDIUM', 'NORMAL', true, '16~24℃', '피닉스야자는 열대와 아열대 지역이 원산지로, 실내에서 잘 자라는 식물이에요. 이 식물은 우아한 녹색 잎이 특징이며, 생육 속도가 느려 장기간 실내에서 기를 수 있어요. 공기 중의 크실렌을 제거하는 데 효과적이며, 실내 공기 정화에 도움을 줘요.', '피닉스야자는 독성이 없어 안전하게 키울 수 있어요.', NULL, true, now(), now()),
(250, 'Dracaena deremensis ''Janet Craig''', '드라세나 자넷 크레이그', 'NORMAL', 'LOW', 'EASY', false, '16~24℃', '드라세나 자넷 크레이그는 짙은 녹색의 넓고 긴 잎이 특징인 실내식물이에요. 이 식물은 실내의 휘발성 유해물질, 특히 트리클로로에틸렌을 제거하는 데 효과적이에요. 관리가 쉬워 현대적인 인테리어에 잘 어울리며, 적절한 관리만으로 10년 이상 재배할 수 있어요.', '드라세나는 섭취 시 구토와 설사를 유발할 수 있는 독성을 가지고 있어요. 특히 반려동물에게 주의가 필요해요.', NULL, true, now(), now()),
(251, 'Ficus elastica [인도고무나무]', '인도고무나무', 'NORMAL', 'LOW', 'EASY', false, '16~27℃', '인도고무나무는 인도와 말레이시아가 원산지인 뽕나무과 식물이에요. 잎이 두껍고 광택이 나는 짙은 녹색을 띠며, 적정한 환경에서는 키가 2.5m까지 자랄 수 있어요. 실내의 화학적 독소를 제거하는 능력이 뛰어나고 관리가 쉬워 인기가 많아요.', '인도고무나무의 수액은 피부나 점막을 자극할 수 있어요. 어린이와 애완동물이 있는 가정에서는 주의가 필요해요.', NULL, true, now(), now()),
(252, 'Chamaedorea seifrizii [세이프리찌야자]', '세이프리찌야자', 'NORMAL', 'MEDIUM', 'EASY', true, '16~24℃', '세이프리찌야자는 대나무를 닮은 줄기로 인해 대나무야자라고도 불려요. 관리가 쉬워 실내식물로 인기가 높으며, 특히 겨울철 난방으로 건조해진 실내의 습도를 높이는 데 효과적이에요. 포름알데히드, 벤젠, 트리클로로에틸렌을 제거하는 데 탁월한 공기정화 능력을 가지고 있어요.', '세이프리찌야자는 독성이 없어 안전한 식물이에요.', NULL, true, now(), now()),
(253, 'Chrysalidocarpus lutescens', '아레카야자', 'NORMAL', 'MEDIUM', 'EASY', true, '18~24℃', '아레카야자는 미우주항공국(NASA)에서 포름알데히드 제거 능력이 가장 우수한 식물로 선정되었어요. 이 식물은 실내환경에 대한 적응력이 매우 높으며, 많은 양의 수분을 공기 중에 내뿜어요. 또한 잎의 곡선과 직선이 조화로워 관상용으로도 인기가 많아요.', '아레카야자는 독성이 없어요.', NULL, true, now(), now())
ON CONFLICT (species_id) DO NOTHING;

-- species_id 를 직접 넣었으므로, 사진 식별로 새 식물이 추가될 때 id 가 겹치지 않게 번호를 맞춘다.
SELECT setval(pg_get_serial_sequence('plant_species', 'species_id'),
              (SELECT MAX(species_id) FROM plant_species));
COMMIT;
